export const obligationsAndContracts_478_722: Record<string, string> = {
  "478": "البيع عقد بمقتضاه ينقل أحد المتعاقدين للآخر ملكية شيء أو حق في مقابل ثمن يلتزم هذا الآخر بدفعه له.",
  "479": "البيع المعقود من المريض في مرض موته تطبق عليه أحكام الفصل 344، إذا أجري لأحد ورثته بقصد محاباته، كما إذا بيع له شيء بثمن يقل كثيرا عن قيمته الحقيقية، أو اشتري منه شيء بثمن يجاوز قيمته.\nأما البيع المعقود من المريض لغير وارث فتطبق عليه أحكام الفصل 345.",
  "480": "متصرفو البلديات والمؤسسات العامة، والأوصياء، والمساعدون القضائيون أو المقدمون والآباء الذين يديرون أموال أبنائهم، وأمناء التفليسة (السنادكة)، ومصفو الشركات، لا يسوغ لهم اكتساب أموال من ينوبون عنهم إلا إذا كانوا يشاركونهم على الشيوع في ملكية الأموال التي هي موضوع التصرف. كما أنه لا يجوز لهؤلاء الأشخاص أن يجعلوا من أنفسهم محالا لهم بالديون التي على من يتولون إدارة أموالهم. وليس لهؤلاء الأشخاص كذلك أن يأخذوا أموال من ينوبون عنهم على سبيل المعاوضة أو الرهن.\nإلا أنه يمكن إجازة الحوالة أو البيع أو المعاوضة أو الرهن ممنحصل التصرف لصالحه، إذا كانت له أهلية التفويت، أو من المحكمة أو من أي سلطة مختصة أخرى مع مراعاة الأحكام المتعلقة بذلك والواردة في ظهير المسطرة المدنية.",
  "481": "لا يسوغ للسماسرة ولا للخبراء أن يشتروا، لا بأنفسهم ولا بوسطاء عنهم، الأموال المنقولة أو العقارية التي يناط بهم بيعها أو تقويمها كما أنه لا يسوغ لهم أن يأخذوا هذه الأموال على سبيل المعاوضة أو الرهن. ويترتب على مخالفة هذا الفصل الحكم بالبطلان وبالتعويضات.",
  "482": "يعتبر وسطاء في الحالات المنصوص عليها في الفصلين 480 و481 السابقين زوجات الأشخاص المذكورين فيهما وأبناؤهم وإن كانوا رشداء.",
  "483": "يقع صحيحا بيع جزء محدد من الفضاء الطليق أو الهواء العمودي الذي يرتفع فوق بناء قائم فعلا، ويسوغ للمشتري أن يبني فيه، بشرط تحديد طبيعة البناء وأبعاده. ولكن لا يسوغ للمشتري أن يبيع الهواء العمودي الذي يعلوه بغير رضى البائع الأصلي.",
  "484": "يبطل بين المسلمين بيع الأشياء المعتبرة من النجاسات وفقا لشريعتهم مع استثناء الأشياء التي تجيز هذه الشريعة الاتجار فيها، كالأسمدة الحيوانية المستخدمة في أغراض الفلاحة.",
  "485": "بيع ملك الغير يقع صحيحا:\n1 - إذا أقره المالك؛\n2 - إذا كسب البائع فيما بعد ملكية الشيء.\nوإذا رفض المالك الإقرار، كان للمشتري أن يطلب فسخ البيع. وزيادة على ذلك، يلتزم البائع بالتعويض، إذا كان المشتري يجهل، عند البيع أن الشيء مملوك للغير.\nولا يجوز إطلاقا للبائع أن يتمسك ببطلان البيع بحجة أن الشيء مملوك للغير.",
  "486": "يسوغ أن يرد البيع على شيء غير محدد إلا بنوعه. ولكن البيع لا يصح، في هذه الحالة، إلا إذا ورد على أشياء مثلية محددة تحديدا كافيا، بالنسبة إلى العدد والكمية والوزن أو المقياس والصنف، على نحو يجيء معه رضى المتعاقدين على بينة وتبصر.",
  "487": "يجب أن يكون الثمن الذي ينعقد عليه البيع معينا. ولا يسوغ أن يعهد بتعيينه إلى أحد من الغير، كما أنه لا يسوغ أن يقع الشراء بالثمن الذي اشترى به الغير ما لم يكن هذا الثمن معروفا من المتعاقدين. ومع ذلك، يجوز الركون إلى الثمن المحدد في قائمة أسعار السوق، أو إلى تعريفة معينة أو إلى متوسط أسعار السوق، إذا ورد البيع على بضائع لا يتعرض ثمنها للتقلبات. أما إذا ورد البيع، على بضائع، يتعرض ثمنها للتقلبات، فيفترض في المتعاقدين أنهما ركنا إلى متوسط الأسعار التي تجري بها الصفقات.",
  "488": "يكون البيع تاما بمجرد تراضي عاقديه، أحدهما بالبيع والآخر بالشراء، وباتفاقهما على المبيع والثمن وشروط العقد الأخرى.",
  "489": "إذا كان المبيع عقارا أو حقوقا عقارية أو أشياء أخرى يمكن رهنها رهنا رسميا، وجب أن يجري البيع كتابة في محرر ثابت التاريخ. ولا يكون له أثر في مواجهة الغير إلا إذا سجل في الشكل المحدد بمقتضى القانون.",
  "490": "إذا حصل البيع جزافا، فإنه يكون تاما بمجرد أن يتراضى المتعاقدان على المبيع والثمن وشروط العقد الأخرى، ولو لم تكن الأشياء التي يرد عليها قد وزنت أو عدت أو قيست أو كيلت.\nوالبيع الجزافي هو الذي يرد بثمن واحد على جملة أشياء، دون أن يعتبر عددها أو وزنها أو قياسها إلا لأجل تعيين ثمن المجموع.",
  "491": "يكسب المشتري بقوة القانون ملكية الشيء المبيع، بمجرد تمام العقد بتراضي طرفيه.",
  "492": "بمجرد تمام البيع، يسوغ للمشتري تفويت الشيء المبيع ولو قبل حصول التسليم، ويسوغ للبائع أن يحيل حقه في الثمن ولو قبل الوفاء. وذلك ما لم يتفق العاقدان على خلافه. ولا يعمل بهذا الحكم في بيوع المواد الغذائية المنعقدة بين المسلمين.",
  "493": "بمجرد تمام العقد، يتحمل المشتري الضرائب وغيرها من الأعباء التي يتحملها الشيء المبيع ما لم يشترط غير ذلك. ويقع على عاتقه أيضا مصروفات حفظ المبيع وجني ثماره. وعلاوة على ذلك، يتحمل المشتري تبعة هلاك المبيع، ولو قبل حصول التسليم، ما لم يتفق على غير ذلك.",
  "494": "إذا وقع البيع بالقياس أو الكيل أو العد أو على شرط التجربة أو على شرط المذاق أو على أساس مجرد الوصف، فإن البائع يبقى متحملا بتبعة هلاك المبيع، مادام لم يجر قياسه أو كيله أوعده أو تجربته أو مذاقه أو فحصه ولم يحصل قبوله من المشتري أو من نائبه، وذلك حتى ولو كان المبيع موجودا بالفعل في يد المشتري.",
  "495": "إذا كان البيع على التخيير، مع تحديد أجل للاختيار فإن المشتري لا يتحمل تبعة الهلاك، إلا من وقت تحقق الشرط، ما لم يتفق على غير ذلك.",
  "496": "يبقى الشيء المبيع أثناء نقله في ضمان البائع، الذي يتحمل تبعة هلاكه، إلى أن يتسلمه المشتري.",
  "497": "في حالة بيع الثمار على الأشجار ومنتجات البساتين والمحصولات قبل جنيها يتحمل البائع تبعة هلاك المبيع إلى تمام نضجه.",
  "498": "يتحمل البائع بالتزامين أساسيين:\n1 - الالتزام بتسليم الشيء المبيع؛\n2 - الالتزام بضمانه.",
  "499": "يتم التسليم حين يتخلى البائع أو نائبه عن الشيء المبيع ويضعه تحت تصرف المشتري بحيث يستطيع هذا حيازته بدون عائق.",
  "500": "يتم التسليم بطرق مختلفة:\n1 - تسلم العقارات بتخلي البائع عنها، وبتسليم مفاتيحها إذا كانت من المباني، بشرط ألا يكون ثمة عائق يمنع المشتري من وضع اليد عليها؛\n2 - تسلم الأشياء المنقولة بمناولتها من يد إلى يد أو بتسليم مفاتيح العمارة أو الصندوق الموضوعة فيه، أو بأي وجه آخر جرى به العرف؛\n3 - يتم التسليم ولو بمجرد رضى الطرفين، إذا كان سحب المبيع من يد البائع غير ممكن وقت البيع، أو كان المبيع موجودا من قبل في يد المشتري على وجه آخر؛\n4 - إذا كان المبيع عند البيع موجودا في مستودع عام، فإن حوالة أو مناولة شهادة إيداعه أو تذكرة شحنه أو نقله تكون بمثابة تسليمه.",
  "501": "يتم تسليم الحقوق المعنوية، كحق المرور مثلا، إما بتسليم السندات التي تثبت وجودها، وإما بالاستعمال الذي يباشره المشتري لها برضى البائع. وإذا اقتضى استعمال الحقوق المعنوية حيازة شيء معين، وجب على البائع أن يمكن المشتري من وضع اليد عليه بدون عائق.",
  "502": "يجب أن يتم التسليم في المكان الذي كان الشيء موجودا فيه عند البيع، ما لم يتفق على غير ذلك.\nإذا ذكر في عقد البيع أن الشيء موجود في مكان آخر غير الذي كان موجودا فيه حقيقة، وجب على البائع نقله إلى المكان المبين في العقد إذا طلب المشتري ذلك.",
  "503": "إذا لزم نقل المبيع من مكان إلى مكان آخر، فإن تسليمه لا يتم إلا في وقت وصوله إلى المشتري أو إلى نائبه.",
  "504": "يجب أن يحصل التسليم فور إبرام العقد، إلا ما تقتضيه طبيعة الشيء المبيع أو العرف من زمن.\nولا يجبر البائع الذي لم يعط المشتري أجلا للوفاء بالثمن على تسليم المبيع، إذا لم يعرض المشتري دفع ثمنه في مقابل تسلمه.\nولا يقوم إعطاء الكفيل أو أي تأمين آخر مقام دفع الثمن.",
  "505": "إذا بيعت عدة أشياء صفقة واحدة، كان للمشتري أن يحبسها كلها حتى يستوفي الثمن بتمامه، ولو كان قد سمي لكل شيء ثمنه على حدة.",
  "506": "ليس للبائع أن يمتنع من تسليم الشيء المبيع:\n1 - إذا رخص لأحد من الغير في قبض الثمن أو ما تبقى منه؛\n2 - إذاقبل إنابة على الغير من أجل استيفاء الدين أو ما تبقى منه؛\n3 - إذا منح، بعد العقد، أجلا للوفاء بالثمن.",
  "507": "لا يجبر البائع على تسليم الشيء المبيع، ولو كان قد منح أجلا للوفاء بالثمن:\n1 - إذا أعسر المشتري بعد البيع؛\n2 - إذا كان المشتري مفلسا بالفعل عند البيع بدون علم البائع؛\n3 - إذا قلل المشتري التأمينات المقدمة منه لضمان الوفاء بالثمن على وجه يعرض البائع لخطر ضياعه عليه.",
  "508": "إذا باشر البائع حق الحبس المقرر بمقتضى الفصول السابقة، كان مسؤولا عن الشيء مسؤولية المرتهن رهنا حيازيا لمنقول عن المرهون الذي في حوزه.",
  "509": "مصروفات التسليم كالتي يقتضيها القياس أو الوزن أو العد أو الكيل، تقع على عاتق البائع.\nوإذا كان المبيع حقا معنويا، وقعت على عاتق البائع أيضا المصروفات اللازمة لإنشاء هذا الحق أو لنقله.\nوالكل ما لم تقض العادات المحلية أو اتفاقات الطرفين بخلافه.",
  "510": "إذا وقع البيع بواسطة سمسار، كانت مصروفات السمسرة على البائع، ما لم تقض العادات المحلية أو اتفاقات الطرفين بخلافه.",
  "511": "على المشتري مصروفات رفع الشيء المبيع وتسلمه، وكذلك مصروفات أداء الثمن وتلك التي يقتضيها الصرف والتوثيق والتسجيل ومصروفات التمبر اللازمة لرسم الشراء وعليه أيضا مصروفات التغليف والشحن والنقل.\nوتشمل مصروفات التسلم رسوم حق المرور (الترانزيت)، والمكوس والضرائب الجمركية التي تجبى عند انتقال الشيء ووصوله.\nوالكل ما لم يجر العرف أو الاتفاق بخلافه.",
  "512": "يجب تسليم الشيء في الحالة التي كان عليها عند البيع. ويمتنع على البائع إجراء التغيير فيه ابتداء من هذا الوقت.",
  "513": "إذا كان المبيع شيئا معينا، وهلك هذا الشيء أو تعيب قبل التسليم بفعل البائع أو بخطإه، كان للمشتري الحق في أن يطالبه بقيمته أو بتعويض يعادل النقص في قيمته، على نحو ما كان يمكن أن يفعله ضد أي شخص من الغير.\nوإذا ورد البيع على شيء مثلي، إلتزم البائع بأن يسلم مثيلا له في صنفه ومقداره والكل مع حفظ حق المشتري في تعويض أكبر، إذا كان لهذا التعويض محل.",
  "514": "إذا هلك الشيء المبيع أو تعيب قبل التسليم، بفعل المشتري أو بخطإه وجب على هذا الأخير تسلمه في الحالة التي هو عليها، ودفع الثمن كاملا.",
  "515": "للمشتري ثمار الشيء وزوائده، سواء كانت مدنية أم طبيعية، ابتداء من وقت تمام البيع. ويجب تسليمها إليه معه، ما لم يقض الاتفاق بخلافه.",
  "516": "الالتزام بتسليم الشيء يشمل أيضا توابعه، وفقا لما يقضي به اتفاق الطرفين أو يجري به العرف.\nفإن لم يوجد اتفاق ولا عرف، اتبعت القواعد الواردة فيما يلي:",
  "517": "بيع الأرض يشمل ما يوجد فيها من مباني وأشجار، كما يشمل المزروعات التي لما تنبت، والثمار التي لما تعقد.\nولا يشمل البيع الثمار المعقودة، ولا المحصولات المعلقة بالأغصان أو الجذور ولا النباتات المغروسة في الأوعية، ولا تلك المعدة لقلعها وإعادة غرسها، ولا الأشجار اليابسة التي لا ينتفع بها إلا خشبا، ولا الأشياء المدفونة بفعل الإنسان والتي لا يرجع عهدها إلى قديم الزمان.",
  "518": "بيع البناء يشمل الأرض التي أقيم عليها، كما يشمل ملحقاته المتصلة به اتصال قرار كالأبواب والنوافذ والمفاتيح التي تعتبر جزءا متمما للأقفال. ويشمل كذلك الأرحية والأدراج والخزائن المثبتة فيه، وأنابيب المياه والمواقد المثبتة بجدرانه.\nولا يشمل بيع البناء الأشياء غير الثابتة التي يمكن إزالتها بلا ضرر، ولا مواد البناء المجمعة لإجراء الإصلاحات ولا تلك التي فصلت عنه بقصد استبدال غيرها بها.",
  "519": "ويشمل بيع العقار كذلك الخرائط وتقدير المصروفات، والحجج والوثائق المتعلقة بملكيته، وإذا تعلقت حجج الملكية بالمبيع وبغيره من الأشياء التي لا تدخل في البيع، لم يكن البائع ملتزما إلا بأن يسلم نسخة رسمية للجزء المتعلق منها بالعين المبيعة.",
  "520": "خلايا النحل وبروج الحمام غير الثابتة لا تعتبر جزءا من العين المبيعة.",
  "521": "البستان والأراضي الأخرى، سواء كانت مغروسة أم لا، الموجودة خارج الدار لا تعتبر من توابعها، ولو كانت متصلة بها بباب داخلي إلا:\n1 - إذا كان البستان أو الأراضي بالنسبة إلى البناء، من الصغر جدا بحيث يجب اعتبارها من توابعه؛\n2 - إذا تبين من تخصيص المالك أن البستان أو الأراضي كانت معتبرة من توابع الدار.",
  "522": "إذا تعلق البيع بالأشياء التي تتجدد بعد قطعها أو جني غلتها كالدرق والفصة وكان واردا على قطفة أو جذة منها، فإنه لا يشمل خلفها. ويشمل بيع الخضر والأزهار والفاكهة ما وجد منها معلقا بأصله، وكذلك ما ينضج منها أو ينفتح بعد البيع إذا كان يعتبر من التوابع لا من الخلف.",
  "523": "بيع الحيوان يشمل:\n1 - صغيره الذي يرضعه؛\n2 - الصوف أو الوبر أو الشعر المتهيئ للجز.",
  "524": "بيع الأشجار يشمل الأرض القائمة عليها، كما يشمل، ثمارها التي لم تعقد.\nالثمار المعقودة للبائع، ما لم يشترط غير ذلك.",
  "525": "النقود والأشياء الثمينة الموجودة داخل شيء منقول لا تعتبر داخلة في البيع الذي يرد عليه، ما لم يشترط غير ذلك.",
  "526": "الأشياء التي تباع بالوزن والعد، ولا يكون في أثمانها تفاوت محسوس، والأشياء التي يمكن تقسيمها بغير ضرر، يسوغ بيعها بثمن إجمالي واحد، أو على أساس سعر معين لكل وحدة كيل أو وزن.\nوإذا وجد المقدار المحدد في العقد كاملا عند التسليم، لزم البيع في الكل، أما إذا وجد فرق بالزيادة أو النقصان وسواء كان البيع بثمن إجمالي واحد أو بثمن مقدر على أساس سعر الوحدة، وجب إتباع القواعد الآتية:\nإذا وجدت زيادة، كانت من حق البائع، وإذا وجد نقصان، كان للمشتري الخيار بين أن يفسخ العقد بالنسبة إلى الكل، وبين أن يقبل القدر المسلم ويدفع الثمن بنسبته.",
  "527": "إذا كان محل البيع أشياء تباع بالعدد وفي أثمانها تفاوت محسوس طبقت القواعد الآتية:\nإذا بيعت هذه الأشياء جملة وبثمن إجمالي واحد، فإن كل فرق بالزيادة أو النقصان يبطل البيع. وإذا بيعت على أساس سعر الوحدة وتبين فرق بالزيادة بطل البيع، وإذا كان الفرق بالنقصان، كان للمشتري الخيار بين أن يفسخ البيع في الكل، وبين أن يقبل المقدار المسلم على أن يدفع الثمن بنسبته.",
  "528": "إذا كان محل البيع أشياء تباع بالوزن أو القياس ويضرها التبعيض ومن بينها الأراضي المبيعة بالقياس، اتبعت القواعد الآتية:\nأ - إذا بيع الشيء بتمامه بثمن إجمالي واحد، كانت الزيادة للمشتري من غير أن يكون للبائع خيار فسخ البيع. وإذا وجد فرق بالنقصان، حق للمشتري أن يفسخ البيع أو أن يقبل القدر المسلم مع دفع الثمن المحدد في العقد؛\nب - إذا بيع الشيء على أساس سعر وحدة الكيل ووجد فرق بالزيادة أو النقصان، كان للمشتري الخيار بين أن يفسخ العقد، وبين أن يقبل القدر المسلم، مع دفع الثمن بنسبته.",
  "529": "إذا بيع الشيء جملة واحدة، أو باعتباره معينا بذاته، وذكر في العقد قدره عدا أو وزنا أو سعة، لم يكن للبائع حق في زيادة الثمن ولا للمشتري حق في إنقاصه، إلا إذا بلغ الفرق بين القدر المذكور في العقد والقدر الحقيقي للشيء جزءا من عشرين زيادة أو نقصانا.\nكل ذلك ما لم يوجد اتفاق أو عرف يخالفه.",
  "530": "إذا كان لزيادة الثمن محل، بسبب الزيادة في المقدار أو الوزن على مقتضى الفصل السابق، كان للمشتري الخيار بين أن يتخلى عن العقد أو أن يقدم الزيادة في الثمن.",
  "531": "دعوى فسخ العقد ودعوى إنقاص الثمن أو تكملته، وفقا للفصول السابقة يلزم رفعها خلال السنة التي تبدأ من التاريخ المحدد بمقتضى العقد لبدء انتفاع المشتري أو للتسليم، أو من تاريخ العقد إن لم يحدد فيه تاريخ لبدء الانتفاع أو للتسليم. وإذا لم ترفع تلك الدعاوى في الأجل المذكور، سقطت.",
  "532": "الضمان الواجب على البائع للمشتري يشمل أمرين:\nأ - أولهما حوز المبيع والتصرف فيه، بلا معارض (ضمان الاستحقاق)؛\nب - وثانيهما عيوب الشيء المبيع (ضمان العيب).\nوالضمان يلزم البائع بقوة القانون، وإن لم يشترط. وحسن نية البائع لا يعفيه من الضمان.",
  "533": "الالتزام بالضمان يقتضي من البائع الكف عن كل فعل أو مطالبة ترمي إلى التشويش على المشتري أو حرمانه من المزايا التي كان له الحق في أن يعول عليها، بحسب ما أعد له المبيع والحالة التي كان عليها وقت البيع.",
  "534": "ويلتزم البائع أيضا بقوة القانون بأن يضمن للمشتري الاستحقاق الذي يقع ضده، بمقتضى حق كان موجودا عند البيع.\nويكون الاستحقاق واقعا ضد المشتري في الحالات الآتية:\n1 - إذا حرم المشتري من حوز الشيء كله أو بعضه؛\n2 - إذا كان المبيع في حوز الغير ولم يتمكن المشتري من استرداده منه؛\n3 - إذا اضطر المشتري لتحمل خسارة من أجل افتكاك المبيع.",
  "535": "استحقاق جزء معين من المبيع كاستحقاقه كله، إذا بلغ هذا الجزء، بالنسبة إلى الباقي من الأهمية بحيث إن المشتري ما كان ليشتري بدون ذلك الجزء.\nويسري نفس الحكم إذا كانت العين مثقلة بحقوق ارتفاق غير ظاهرة أو بحقوق أخرى لم يصرح بها عند البيع.",
  "536": "إذا كانت العين المبيعة مثقلة بحق من حقوق الارتفاق الضرورية الملازمة لها، بمقتضى طبيعة الأمور، كحق المرور الثابت على أرض تحصر أخرى عن الطريق، فإن المشتري لا يثبت له حق الرجوع على البائع، إلا إذا ضمن هذا الأخير تمام خلو العين من كل عبء.",
  "537": "إذا وجهت على المشتري دعوى، بسبب الشيء المبيع، وجب عليه أن يعلم البائع بدعوى الاستحقاق، عند تقديم المدعي البينة على دعواه. وإذ ذاك تنبهه المحكمة بأنه إذا استمر في الدعوى باسمه الشخصي، يعرض نفسه لضياع حقه في الرجوع على البائع، فإذا فضل، برغم هذا التنبيه، أن يدافع مباشرة في الدعوى فقد كل حق في الرجوع على البائع.",
  "538": "إذا استحق المبيع كله من يد المشتري، من غير أن يقع من جانبه اعتراف بحق المستحق كان له أن يطلب استرداد:\n1 - الثمن الذي دفعه ومصروفات العقد التي أنفقت على وجه سليم؛\n2 - المصروفات القضائية التي أنفقها على دعوى الضمان؛\n3 - الخسائر المترتبة مباشرة عن الاستحقاق.",
  "539": "للمشتري الحق في استرداد الثمن كاملا، ولو هلك الشيء الذي حصل استحقاقه أو نقصت قيمته كلا أو بعضا، بفعله أو بخطإه أو نتيجة قوة قاهرة.",
  "540": "البائع سيئ النية ملزم بأن يدفع للمشتري حسن النية كل المصروفات التي أنفقها حتى مصروفات الزينة أو الترف.",
  "541": "إذا كانت قيمة الشيء المستحق قد ازدادت عند حصول الاستحقاق ولو بغير عمل المشتري، فإن الزيادة في القيمة تدخل في مبلغ التعويض، إذا صدر تدليس من البائع.",
  "542": "في حالة الاستحقاق الجزئي الذي يبلغ من الأهمية حدا بحيث يعيب الشيء المبيع، وبحيث إن المشتري كان يمتنع عن الشراء لو علم به، يثبت للمشتري الخيار بين استرداد ثمن الجزء الذي حصل استحقاقه والاحتفاظ بالبيع بالنسبة إلى الباقي، وبين فسخ البيع واسترداد كل الثمن.\nوإذا لم يبلغ الاستحقاق الجزئي من الأهمية الحد الكافي لتبرير فسخ البيع لم يثبت للمشتري إلا الحق في إنقاص الثمن بقدر ما استحق.",
  "543": "إذا ورد البيع على عدة أشياء منقولة، وحصل شراؤها كلها جملة واحدة وبثمن واحد، ثم استحق بعضها، كان للمشتري الخيار بين أن يفسخ العقد ويسترد الثمن، وبين أن يطلب إنقاص الثمن بقدر ما استحق.\nإلا أنه إذا كان من طبيعة الأشياء المبيعة عدم إمكان إجراء الفصل بينها بغير ضرر، فإنه لا يكون للمشتري الفسخ إلا بالنسبة إلى الكل.",
  "544": "يسوغ أن يتفق المتعاقدان على أن البائع لا يتحمل بأي ضمان أصلا.\nإلا أنه لا يكون لهذا الشرط من أثر إلا إعفاء البائع من التعويضات، فلا يمكنه أن يحلل البائع من التزامه برد الثمن الذي قبضه، كله أو بعضه في حالة الاستحقاق.\nولا يكون لشرط عدم الضمان أي أثر:\n1 - إذا بني الاستحقاق على فعل شخصي للبائع نفسه؛\n2 - إذا وقع تدليس من البائع، كما إذا باع ملك الغير على علم منه وكما إذا كان يعرف سبب الاستحقاق، ولم يصرح به.\nوفي هاتين الحالتين الأخيرتين، يلتزم البائع أيضا بالتعويض.",
  "545": "يلتزم البائع برد الثمن أو بتحمل إنقاصه، ولو كان المشتري عالما باحتمال الاستحقاق أو بوجود حقوق تثقل المبيع.",
  "546": "لا يلتزم البائع بأي ضمان أصلا:\nأ - إذا وقع انتزاع المبيع بالإكراه أو نتيجة قوة قاهرة؛\nب - إذا حصل الانتزاع بفعل السلطة، ما لم يكن فعلها مبنيا على حق سابق ثابت لها يخولها العمل على احترامه، أو على فعل يعزى للبائع؛\nج - إذا حصل للمشتري عرقلة في التصرف، نتيجة تعد من الغير، بدون أن يدعي أي حق على العين المبيعة.",
  "547": "البائع، ولو أدخل في الدعوى في وقت مفيد، لا يتحمل بأي ضمان، إذا حصل الاستحقاق بغش المشتري أو بخطإه، وكان هذا الخطأ هو السبب الدافع للحكم الذي قضى بالاستحقاق، وعلى وجه الخصوص:\nأ - إذا ترك المشتري التقادم البادئ قبل البيع والساري ضده يتم أو إذا أهمل إتمام تقادم بدأه البائع؛\nب - إذا بني الاستحقاق على فعل أو سبب شخصي للمشتري.",
  "548": "لا يفقد المشتري حقه في الرجوع بالضمان على البائع، إذا كان لم يتمكن، بسبب غيابه، من إخطاره في وقت مفيد، واضطر نتيجة لذلك أن يدافع عن نفسه وحده ضد المستحق.",
  "549": "يضمن البائع عيوب الشيء التي تنقص من قيمته نقصا محسوسا، أو التي تجعله غير صالح لاستعماله فيما أعد له بحسب طبيعته أو بمقتضى العقد. أما العيوب التي تنقص نقصا يسيرا من القيمة أو الانتفاع، وتلك التي جرى العرف على التسامح فيها، فلا تخول الضمان.\nويضمن البائع أيضا وجود الصفات التي صرح بها أو التي اشترطها المشتري.",
  "550": "إلا أنه إذا كان المبيع مما لا يمكن التعرف على حقيقة حالته إلا بإجراء تغيير في طبيعته، كالثمار في قشورها، فإن البائع لا يضمن العيوب الخفية إلا إذا التزم بذلك صراحة أو إذا كان العرف المحلي يفرض عليه هذا الضمان.",
  "551": "في البيوع التي تنعقد على مقتضى أنموذج، يضمن البائع توفر صفات الأنموذج في المبيع. وإذا هلك الأنموذج أو تعيب، وجب على المشتري أن يثبت أن البضاعة غير مطابقة له.",
  "552": "لا يضمن البائع إلا العيوب التي كانت موجودة عند البيع، إذا كان المبيع شيئا معينا بذاته، أو عند التسليم إذا كان المبيع شيئا مثليا بيع بالوزن أو القياس أو على أساس الوصف.",
  "553": "إذا ورد البيع على الأشياء المنقولة، عدا الحيوانات، وجب على المشتري أن يفحص الشيء المبيع فور تسلمه، وأن يخطر البائع حالا بكل عيب يلزمه ضمانه، خلال السبعة الأيام التالية للتسلم.\nوإذا لم يجر ما سبق، اعتبر الشيء مقبولا، ما لم تكن العيوب مما لا يمكن التعرف عليه بالفحص العادي، أو كان المشتري قد منع لسبب خارج عن إرادته، من فحص الشيء المبيع. وفي هذه الحالة يجب إخطار البائع بعيوب الشيء فور اكتشافها. فإن لم يحصل الإخطار اعتبر الشيء مقبولا، ولا يسوغ للبائع سيئ النية أن يتمسك بهذا التحفظ الأخير.",
  "554": "إذا ظهر عيب في المبيع، وجب على المشتري أن يعمل فورا على إثبات حالته بواسطة السلطة القضائية أو بواسطة خبراء مختصين بذلك مع حضور الطرف الآخر أو نائبه إن كان موجودا في المكان، فإذا لم يقم المشتري بإثبات حالة المبيع على وجه سليم، تعين عليه أن يثبت أن العيب كان موجودا فعلا عند تسلمه المبيع. ولا يتعين إثبات حالة المبيع إذا أبرم البيع على أساس أنموذج لم ينازع في ذاتيته.\nوإذا كانت البضاعة آتية من مكان آخر، ولم يكن للبائع من يمثله في محل التسليم وجب على المشتري أن يعمل على حفظها مؤقتا.\nوإذا خيف من خطر تعيب سريع كان للمشتري الحق في أن يعمل على بيع الشيء بحضور ممثل السلطة المختصة في مكان وجوده، وذلك بعد قيامه بإثبات حالته على نحو ما ذكر. ويصبح هذا الإجراء واجبا إذا اقتضته مصلحة البائع. وعلى المشتري أن يبادر بإخطار البائع بكل ما سبق وإلا وجب عليه تعويض الضرر.",
  "555": "مصروفات رد البضاعة إلى مصدرها في حالة الفصل السابق، تقع على عاتق البائع.",
  "556": "إذا ثبت الضمان، بسبب العيب أو بسبب خلو المبيع من صفات معينة كان للمشتري أن يطلب فسخ البيع ورد الثمن، وإذا فضل المشتري الاحتفاظ بالمبيع، لم يكن له الحق في أن ينقص من الثمن.\nوللمشتري الحق في التعويض:\nأ - إذا كان البائع يعلم عيوب المبيع أو يعلم خلوه من الصفات التي وعد بها ولم يصرح بأنه يبيع بغير ضمان. ويفترض هذا العلم موجودا دائما إذا كان البائع تاجرا أو صانعا، وباع منتجات الحرفة التي يباشرها؛\nب - إذا صرح البائع بعدم وجود العيوب، ما لم تكن العيوب قد ظهرت بعد البيع أو كان يمكن للبائع أن يجهلها بحسن نية؛\nج - إذا كانت الصفات التي ثبت خلو المبيع منها قد اشترط وجودها صراحة أو كان عرف التجارة يقتضيها.",
  "557": "إذا ورد البيع على مجموع من أشياء محددة، وكان جزء منها معيبا كان للمشتري أن يستعمل حق الاختيار المخول له بمقتضى الفصل 556 وإذا ورد البيع على أشياء مثلية، لم يكن للمشتري إلا أن يطلب تسليم مثلها في النوع خالية من العيب، مع حفظ حقه في المطالبة بالتعويض إذا كان له محل.",
  "558": "إذا بيعت عدة أشياء مختلفة صفقة واحدة بثمن إجمالي واحد، كان للمشتري ولو بعد التسليم، أن يطلب فسخ البيع بالنسبة إلى الجزء المتعيب وحده من هذه الأشياء ورد ما يقابله من الثمن. إلا أنه إذا كانت الأشياء المبيعة مما لا يمكن تجزئته بغير ضرر كالأشياء المزدوجة. فإن المشتري لا يكون له أن يطلب الفسخ إلا بالنسبة إلى مجموع الصفقة.",
  "559": "الفسخ لعيب في الشيء الأصلي يلحق توابع هذا الشيء، ولو حدد لها ثمن مستقل.\nعيب الشيء التابع لا يكون سببا لفسخ بيع الشيء الأصلي.",
  "560": "يحصل إنقاص الثمن بتقويم المبيع عند البيع على أساس خلوه من العيب ثم تقويمه على الحالة التي يوجد عليها.\nوإذا بيعت عدة أشياء صفقة واحدة، حصل التقويم على أساس قيمة كل الأشياء المكونة للصفقة.",
  "561": "في حالة فسخ البيع، يلتزم المشتري بأن يرد:\nأولا - الشيء المشوب بالعيب الموجب للضمان، بالحالة التي تسلمه عليها وتوابعه وما كان يعتبر جزءا منه وكذلك الزيادات التي اندمجت فيه بعد البيع؛\nثانيا - ثمار الشيء، من وقت الفسخ بالتراضي، أو من وقت الحكم بالفسخ، وكذلك الثمار السابقة على هذا التاريخ. إلا أنه إذا كانت الثمار غير معقودة فإن المشتري يتملكها إذا كان قد جناها ولو قبل نضجها، كما يتملك أيضا الثمار الناضجة ولو لم يجنها.\nومن ناحية أخرى يلتزم البائع:\nأولا - أن يدفع للمشتري مصروفات الزراعة والري والصيانة ومصروفات الثمار التي ردها إليه؛\nثانيا - أن يرد الثمن الذي قبضه ومصروفات العقد؛\nثالثا - أن يعوض للمشتري الخسائر التي قد يسببها له الشيء المبيع إذا كان وقع تدليس من البائع.",
  "562": "ليس للمشتري الحق في استرداد الثمن أو في إنقاصه، إذا تعذر عليه رد الشيء المبيع في الحالات الآتية:\nأولا - إذا هلك المبيع بحادث فجائي أو بخطأ وقع من المشتري أو من الأشخاص الذين يتحمل المسؤولية عنهم؛\nثانيا - إذا سرق الشيء من المشتري أو اختلس منه؛\nثالثا - إذا حول المشتري الشيء على نحو يصير معه غير صالح لاستعماله فيما أعد له أصلا. إلا أنه إذا لم يكن العيب قد ظهر إلا عند إجراء التحويل أو نتيجة له، فإن المشتري يحتفظ بحقه في الرجوع على البائع.",
  "563": "إذا هلك الشيء المبيع بسبب العيب الذي كان يشوبه أو بحادث فجائي ناتج عن هذا العيب، كان هلاكه على البائع فيلتزم برد الثمن ويلتزم أيضا بالتعويضات إذا كان سيئ النية.",
  "564": "لا محل للفسخ، وليس للمشتري إلا طلب إنقاص الثمن:\nأولا - إذا كان الشيء قد تعيب بخطإه أو بخطأ من يسأل عنهم؛\nثانيا - إذا كان قد استعمل الشيء استعمالا من شأنه أن ينقص من قيمته بكيفية محسوسة. ويطبق نفس الحكم إذا كان قد استعمل الشيء قبل أن يعرف العيب. أما إذا كان قد استعمله بعد ذلك فيطبق حكم الفصل 572.",
  "565": "إذا كان الشيء المبيع حصل تسلمه مشوبا بعيب موجب للضمان، ثم حدث فيه بعد ذلك عيب لا يعزى لخطأ المشتري، كان له الخيار بين أن يحتفظ بالشيء ويرجع بالضمان على أساس العيب الأول وفقا لما يقضي به القانون، وبين أن يرده للبائع مع تحمله نقصا في الثمن الذي دفعه يتناسب مع العيب الجديد الذي ظهر بعد البيع. إلا أنه يسوغ للبائع أن يعرض استرداده الشيء المبيع بالحالة التي هو عليها مع تنازله عن حق الرجوع من أجل العيب الجديد. وفي هذه الحالة يكون للمشتري الخيار بين أن يحتفظ بالشيء على الحالة التي يوجد عليها وبين أن يرده دون أداء أي تعويض.",
  "566": "إذا زال العيب الجديد عادت لصالح المشتري دعوى الضمان على أساس العيب القديم السابق على التسليم.",
  "567": "إنقاص الثمن الحاصل بسبب عيب ثابت لا يمنع المشتري فيما إذا ظهر في المبيع عيب آخر جديد، من أن يطلب إما فسخ البيع وإما إنقاصا جديدا في الثمن.",
  "568": "تنقضي دعوى ضمان العيب إذا زال العيب قبل دعوى الفسخ أو إنقاص الثمن أو في أثنائها، وكان العيب بطبيعته مؤقتا، وليس من شأنه أن يظهر من جديد. أما إذا كان من طبيعة العيب أن يظهر من جديد بعد زواله فإن حكم هذا الفصل لا يطبق.",
  "569": "لا يضمن البائع العيوب الظاهرة ولا العيوب التي كان المشتري يعرفها أو كان يستطيع بسهولة أن يعرفها.",
  "570": "يضمن البائع العيوب التي كان المشتري يستطيع بسهولة أن يعرفها إذا صرح بعدم وجودها.",
  "571": "لا يضمن البائع عيوب الشيء أو خلوه من الصفات المتطلبة فيه:\nأولا - إذا صرح بها؛\nثانيا - إذا اشترط عدم مسؤوليته عن أي ضمان.",
  "572": "دعوى ضمان العيب تنقضي:\nأولا - إذا تنازل المشتري عنها صراحة بعد علمه بالعيب؛\nثانيا - إذا باع المشتري الشيء بعد علمه بالعيب أو تصرف فيه على أي وجه آخر باعتباره مالكا؛\nثالثا - إذا كان المشتري قد خصص الشيء لاستعماله الشخصي وظل يستعمله بعد علمه بالعيب الذي يشوبه. ولا تسري هذه القاعدة على المنازل وغيرها من العقارات المشابهة فإن هذه يستطيع الشخص الاستمرار في سكناها أثناء دعوى فسخ البيع.",
  "573": "كل دعوى ناشئة عن العيوب الموجبة للضمان أو عن خلو المبيع من الصفات الموعود بها يجب أن ترفع في الآجال الآتية، وإلا سقطت:\nبالنسبة إلى العقارات، خلال 365 يوما بعد التسليم؛\nبالنسبة إلى الأشياء المنقولة والحيوانات خلال 30 يوما بعد التسليم بشرط أن يكون قد أرسل للبائع الإخطار المشار إليه في الفصل 553.\nويسوغ تمديد هذه الآجال أو تقصيرها باتفاق المتعاقدين، وتسري أحكام الفصول 371 إلى 377 على سقوط دعوى ضمان العيب.",
  "574": "لا يحق للبائع سيئ النية التمسك بدفوع التقادم المقررة في الفصل السابق، كما لا يحق له التمسك بأي شرط آخر من شأنه أن يضيق حدود الضمان المقرر عليه، ويعتبر سيئ النية كل بائع يستعمل طرقا احتيالية ليلحق بالشيء المبيع عيوبا أو ليخفيها.",
  "575": "لا دعوى لضمان العيب في البيوع التي تجري بواسطة القضاء.",
  "576": "يتحمل المشتري بالتزامين أساسيين:\nالالتزام بدفع الثمن؛\nوالالتزام بتسلم الشيء.",
  "577": "على المشتري دفع الثمن في التاريخ وبالطريقة المحددين في العقد، وعند سكوت العقد يعتبر البيع قد أبرم معجل الثمن، ويلتزم المشتري بدفعه في نفس وقت حصول التسليم.\nمصروفات أداء الثمن على المشتري.",
  "578": "إلا أنه إذا جرى العرف على أن يحصل أداء الثمن داخل أجل محدد أو في أقساط معينة، افترض في المتعاقدين أنهما ارتضيا اتباع حكمه ما لم يشترطا العكس صراحة.",
  "579": "إذا منح أجل لأداء الثمن، بدأ سريانه من وقت إبرام العقد، ما لم يتفق المتعاقدان على ابتدائه من وقت آخر.",
  "580": "يلتزم المشتري بتسلم الشيء المبيع في المكان والوقت اللذين يحددهما العقد. فإذا سكت العقد عن البيان، ولم يجر بشأنه عرف، التزم المشتري بأن يتسلم المبيع فورا، إلا ما يقتضيه تسلمه من زمن. وإذا لم يتقدم المشتري لتسلم المبيع، أو إذا تقدم لتسلمه، ولكنه لم يعرض في نفس الوقت أداء ثمنه، عندما يكون هذا الثمن معجلا، وجب اتباع القواعد العامة المتعلقة بمطل الدائن.\nوإذا لزم تسليم الأشياء المبيعة على عدة دفعات، فإن عدم تسلم الدفعة الأولى يرتب نفس الآثار التي يرتبها عدم تسلم الأشياء كلها.\nكل ذلك ما لم يقع اتفاق بين الطرفين على خلافه.",
  "581": "إذا اشترط بمقتضى العقد أو العرف المحلي أن البيع يفسخ إذا لم تؤد الثمن فإن العقد ينفسخ بقوة القانون بمجرد عدم أداء الثمن في الأجل المتفق عليه.",
  "582": "إذا ورد البيع على منقولات، ولم يمنح أجل لأداء الثمن، فإنه يجوز أيضا للبائع عند عدم أداء الثمن، أن يسترد المنقولات الموجودة في يد المشتري، أو أن يمنعه من بيعها. ولا تقبل دعوى الاسترداد بعد مضي خمسة عشر يوما من تسليم الشيء للمشتري. ويسوغ الاسترداد ولو كان الشيء المبيع قد أدمج في عقار كما تسوغ دعوى الاسترداد ضد الغير، الذين لهم حقوق على هذا العقار.\nويخضع الاسترداد، في حالة الإفلاس للقواعد الخاصة بالإفلاس.",
  "583": "إذا حصل للمشتري تشويش في انتفاعه بالشيء المبيع أو كان هناك سبب جدي للخوف من وقوعه قريبا، وذلك اعتمادا على سند سابق على البيع، كان له الحق في حبس الثمن مادام البائع لم يوقف التشويش. ولكن يسوغ للبائع أن يجبره على أداء الثمن، إذا قدم كفيلا أو تأمينا آخر كافيا يضمن قيامه برد الثمن ومصروفات العقد عند حصول الاستحقاق.\nوإذا لم يقع التشويش إلا في جزء من المبيع، لم يسغ للمشتري أن يحبس إلا جزءا متناسبا من الثمن، وتحدد الكفالة بالجزء المهدد بالاستحقاق.\nولا يسوغ للمشتري أن يباشر حق حبس الثمن، إذا اشترط أداؤه برغم حصول التشويش له، أو إذا كان يعلم عند البيع خطر الاستحقاق.",
  "584": "أحكام الفصل السابق تسري في حالة اكتشاف المشتري في الشيء المبيع عيبا موجبا للضمان.",
  "585": "البيع مع الترخيص للبائع في استرداد المبيع، أو بيع الثـُّـنْـيَـا، هو الذي يلتزم المشتري بمقتضاه، بعد تمام انعقاده، بأن يرجع المبيع للبائع في مقابل رد الثمن. ويسوغ أن يرد بيع الثـُّـنْـيَـا على الأشياء المنقولة أو العقارية[145].",
  "586": "لا يسوغ أن تشترط رخصة الاسترداد لمدة تتجاوز ثلاث سنوات. فإن اشترطت لمدة أطول من هذا القدر، ردت إليه.",
  "587": "الأجل المحدد للاسترداد قاطع، فلا يجوز للقاضي تمديده ولو كان عدم تمكن البائع من مباشرة رخصة الاسترداد راجعا إلى سبب خارج عن إرادته. إلا أنه إذا كان عدم تمكن البائع من مباشرة رخصة الاسترداد راجعا إلى خطأ المشتري، فإن فوات الأجل المحدد لا يمنع البائع من مباشرة حقه.",
  "588": "للمشتري بشرط الاسترداد، خلال الأجل المحدد له، أن ينتفع بالشيء المبيع باعتباره مالكا له، مع عدم الإخلال بما هو مقرر في الفصل 595 وله أن يقبض ثماره، وأن يباشر كل الدعاوى المتعلقة به، بشرط أن يحصل ذلك منه بغير غش.\nوللمشتري أن يتخذ الإجراءات المقررة لتطهير العقار من الرهون الرسمية التي تثقله.",
  "589": "إذا لم يباشر البائع حقه في الاسترداد في الأجل الذي حدده العاقدان، فقد حقه في استرجاع المبيع.\nأما إذا باشر البائع حقه في الاسترداد، فإن الشيء المبيع يعتبر كأنه لم يخرج عن ملكه أصلا.",
  "590": "يحصل طلب الاسترداد بإخطار البائع للمشتري برغبته في أن يرد له المبيع، ومن الضروري أن يقوم البائع في نفس الوقت بعرض الثمن.",
  "591": "إذا مات البائع، قبل أن يباشر حقه في الاسترداد، انتقل هذا الحق إلى ورثته لما بقي من المدة التي كانت له.",
  "592": "لا يسوغ لورثة البائع أن يباشروا حق الاسترداد إلا مجتمعين، وبالنسبة إلى المبيع كله.\nوإذا لم يتفقوا فيما بينهم، ساغ لمن يرغب منهم في الاسترداد أن يباشره على المبيع كله لحساب نفسه.\nويسري نفس الحكم إذا باع عدة أشخاص، بالاشتراك فيما بينهم، وبعقد واحد شيئا يملكونه على الشياع، من غير أن يحتفظوا لأنفسهم بحق مباشرة استرداد كل واحد حصته.",
  "593": "يسوغ مباشرة دعوى الاسترداد ضد ورثة المشتري مجتمعين.\nولكن إذا قسمت التركة، ووقع الشيء المبيع في نصيب أحد الورثة، أمكن مباشرة دعوى الاسترداد ضده من أجل المبيع كله.",
  "594": "إذا أشهر عُسر البائع، جاز لكتلة دائنيه أن تباشر حق الاسترداد.",
  "595": "يسوغ للبائع بالثـُّـنْـيَـا مباشرة دعواه ضد المشتري الثاني، ولو لم يقع التصريح برخصة الاسترداد في البيع الحاصل لهذا الأخير.",
  "596": "البائع الذي يستعمل حق الاسترداد لا يمكنه أن يحوز الشيء المبيع إلا بعد دفع:\nأولا - الثمن الذي قبضه؛\nثانيا - المصروفات النافعة التي ترتبت عليها زيادة في قيمة الشيء وفي حدود تلك الزيادة. أما مصروفات الترف فلا يكون للمشتري إلا حق إزالة التحسينات التي أحدثها إذا أمكن ذلك بغير ضرر، وليس له أن يسترد لا المصروفات الضرورية ولا مصروفات الصيانة، ولا مصروفات جني الثمار.\nويلتزم المشتري، من ناحية أخرى برد:\nأولا - الشيء وكل الزيادات الطارئة عليه بعد البيع؛\nثانيا - الثمار التي قبضها من تاريخ دفع الثمن أو إيداعه.\nوللمشتري استعمال حق الحبس ضمانا للمدفوعات المستحقة له.\nويطبق كل ما سبق ما لم يتفق المتعاقدان على خلافه.",
  "597": "يسأل المشتري عن تعيب الشيء أو هلاكه الحاصلين بفعله أو بخطإه أو بخطأ الأشخاص الذين تلزمه المسؤولية عنهم، كما أنه يسأل عن التغييرات التي ترتب عنها تحول الشيء تحولا أساسيا إضرارا بالبائع.\nولا يسأل المشتري عن الحادث الفجائي أو القوة القاهرة، ولا عن التغييرات اليسيرة التي لحقت الشيء، وليس للبائع في هذه الحالة طلب إنقاص الثمن.",
  "598": "إذا استرد البائع العين تنفيذا لشرط الاسترداد ترتب على ذلك رجوعها إليه خالية من كل ما عسى أن يكون المشتري قد حملها من تكاليف ورهون رسمية، ولكن البائع يلتزم بتنفيذ عقود الأكرية التي أبرمها المشتري بدون غش، إذا كانت مدتها لا تتجاوز الأجل المشترط للاسترداد وكان تاريخها ثابتا.",
  "599": "إذا ورد بيع الثـُّـنْـيَـا على أرض زراعية[146]، وزرعها المشتري بنفسه أو أكراها لأحد من الغير قام بزراعتها، ثم حصل الاسترداد من البائع خلال السنة الزراعية[147]، كان للمشتري الحق في الاستمرار في وضع يده على الأجزاء المزروعة حتى نهاية السنة الزراعية، في مقابل دفع كرائها، حسبما يقدره أهل الخبرة، عن المدة ما بين حصول الفسخ ونهاية تلك السنة.",
  "600": "إذا سمي الاتفاق (ببيع الثـُّـنْـيَـا) مع كونه يتضمن في الحقيقة رهنا، فإن آثار هذا الاتفاق تخضع في العلاقة بين المتعاقدين لأحكام الرهن الحيازي للمنقول أو الرهن الرسمي، وفقا لظروف الحال، لكن هذا العقد لا يمكن أن يحتج به على الغير، إلا إذا كان قد أبرم على الشكل الذي يتطلبه القانون لقيام الرهن الحيازي على منقول أو الرهن الرسمي.",
  "601": "يسوغ أن يشترط في عقد البيع ثبوت الحق للمشتري أو للبائع في نقضه خلال مدة محددة. ويلزم أن يكون هذا الشرط صريحا، ويجوز الاتفاق عليه إما عند العقد وإما بعده في فصل إضافي[148].",
  "602": "البيع الذي يبرم معلقا على الشرط السابق يعتبر معلقا على شرط واقف، مادام العاقد الذي احتفظ لنفسه بحق الخيار لم يظهر، صراحة أو ضمنا في الأجل المتفق عليه، إرادته في أنه يقصد إمضاء العقد أو نقضه.",
  "603": "إذا لم يحدد العقد أجل الخيار، افترض أن المتعاقدين قد ارتضوا الأجل المقرر بمقتضى القانون أو العرف[149].\nإلا أنه لا يجوز أن تتجاوز الآجال المحددة بمقتضى العرف[150] الآجال المبينة في الفصل التالي.",
  "604": "يجب على المتعاقد الذي احتفظ لنفسه بحق الخيار[151] أن يصرح بما إذا كان يقصد إمضاء العقد أو نقضه في المواعيد الآتية:\nأ - (ظهير25 أبريل 1917) بالنسبة إلى العقارات البلدية والأراضي الزراعية، خلال مدة ستين يوما تبدأ من تاريخ العقد؛\nب - بالنسبة إلى الحيوانات الداجنة وكل الأشياء المنقولة، خلال مدة خمسة أيام.\nومع ذلك يسوغ للمتعاقدين أن يتفقوا على أجل أقصر. وكل اشتراط لأجل أطول يكون باطلا، ويلزم إنقاصه إلى الآجال المبينة فيما سبق.",
  "605": "الأجل المحدد بمقتضى اتفاق المتعاقدين أو القانون قاطع فلا يسوغ للمحكمة تمديده ولو كان المتعاقد الذي احتفظ لنفسه بالخيار لم يستعمل حقه لسبب خارج عن إرادته.",
  "606": "الحق في ثمار المبيع وملحقاته والزيادات الطارئة عليه يبقى موقوفا خلال الأجل المقرر للخيار، وتؤول هذه الأشياء مع المبيع نفسه لمن يكسب ملكيته نهائيا.",
  "607": "إذا اختار المتعاقد إمضاء العقد في الميعاد المحدد بمقتضى الاتفاق أو القانون أصبح البيع باتا، واعتبر الشيء مملوكا للمشتري من يوم إبرام العقد.",
  "608": "إذا ترك المتعاقد الذي احتفظ لنفسه بحق الخيار الأجل ينقضي من غير أن يعلم الآخر بقراره افترض فيه بقوة القانون أنه قد قبل.",
  "609": "يفقد المشتري الحق في رفض مشتراه، إذا صدر منه أي فعل يدل على رغبته في اعتبار نفسه مالكا إياه وعلى الخخصوص:\nأ - إذا تصرف في الشيء بمقتضى رهن أو بيع أو كراء أو استعمله لنفسه؛\nب - إذا عيب الشيء باختياره؛\nج - إذا حول الشيء إلى شيء آخر.\nوعلى العكس من ذلك إذا صدرت الأفعال المذكورة في الأحوال السابقة من طرف البائع افترض أنه اختار نقض البيع، ويفقد بذلك طلب تنفيذه.",
  "610": "إذا مات من له الخيار قبل أن يختار، انتقل الخيار إلى ورثته، وإذا فقد أهلية التعاقد عينت له المحكمة مقدما خاصا، ويجب على هذا المقدم أن يعمل على النحو الذي يكون أكثر اتفاقا مع مصالح ناقص الأهلية.",
  "611": "إذا اختار المتعاقد نقض البيع اعتبر العقد كأن لم يكن، ووجب على كل من المتعاقدين أن يرد للآخر ما سبق أن أخذه منه.\nوتزول الحقوق التي رتبها المشتري خلال أجل الخيار.",
  "612": "المشتري الذي يتعذر عليه رد المبيع أو لا يستطيع رده إلا متعيبا، نتيجة سبب لا يعزى إلى فعله أو خطإه، لا يتحمل أي مسؤولية.",
  "613": "السَّـلـَـم عقد بمقتضاه يعجل أحد المتعاقدين مبلغا محددا للمتعاقد الآخر الذي يلتزم من جانبه، بتسليم مقدار معين من الأطعمة أو غيرها من الأشياء المنقولة في أجل متفق عليه.\nولا يجوز إثبات بيع السَّـلـَـم إلا بالكتابة.",
  "614": "يجب دفع الثمن للبائع كاملا، وبمجرد إبرام العقد.",
  "615": "إذا لم يحدد ميعاد التسليم افترض في المتعاقدين أنهما ارتضيا الركون إلى العرف[152] المحلي.",
  "616": "الأطعمة وغيرها من الأشياء التي يرد العقد عليها يجب أن تكون معينة مقدارا وصنفا ووزنا أو كيلا، بحسب طبيعتها، وإلا بطل البيع. وإذا كانت الأشياء المبيعة مما لا يعد ولا يوزن، كفى أن يحدد صنفها بدقة تامة.",
  "617": "إذا لم يحدد للتسليم مكان، وجب إجراؤه في محل إبرام العقد.",
  "618": "إذا منع المدين، بسبب قوة قاهرة، من تسليم ما وعد به، بغير تقصير منه ولا مَطْـل كان للدائن الخيار بين فسخ العقد واسترداد ما عجله من ثمن، وبين الانتظار حتى السنة التالية.\nوفي السنة التالية، إذا وجد الشيء المبيع، وجب على المشتري تسلمه ولا يبقى له الحق في فسخ العقد. ويسري نفس الحكم إذا كان قد سبق للمشتري تسلم جزء من المبيع. وعلى العكس من ذلك إذا لم يوجد الشيء المبيع، طبق حكم الفقرة الأولى من هذا الفصل.",
  "619": "المُعاوضة عقد بمقتضاه يعطي كل من المتعاقدين للآخر على سبيل الملكية، شيئا منقولا أو عقاريا، أو حقا معنويا، في مقابل شيء أو حق آخر من نفس نوعه أو من نوع آخر.",
  "620": "تتم المُعاوضة بتراضي المتعاقدين.\nإلا أنه إذا كان محل المُعاوضة عقارات أو أشياء أخرى يجوز رهنها رهنا رسميا، وجب تطبيق أحكام الفصل 489.",
  "621": "إذا كان أحد العوضين أكثر من الآخر قيمة، ساغ تعويض الفرق بنقود أو بغيرها من الأشياء، معجلا أو مؤجلا. ولا يسري هذا الحكم بين المسلمين، إذا كان محل المُعاوضة طعاما.",
  "622": "مصروفات العقد تنقسم بقوة القانون بين المُتعاوضَين ما لم يشترطا غير ذلك.",
  "623": "يلتزم كل من المتعاوضين نحو الآخر بنفس الضمان الذي يتحمل به البائع، إما بسبب الاستحقاق، أو بسبب العيوب الخفية في الشيء الذي أعطاه.",
  "624": "إذا كان محل المُعاوضة عقارات أو حقوقا عقارية وقدمت دعوى لفسخها وجب تقييد ذلك على هامش تسجيل عقد المُعاوضة.",
  "625": "تطبق أحكام البيع على المُعاوضة في الحدود التي تسمح بها طبيعتها.",
  "626": "الإجارة نوعان: إجارة الأشياء وهي الكراء، وإجارة الأشخاص أو العمل.",
  "627": "الكراء عقد، بمقتضاه يمنح[161] أحد طرفيه للآخر منفعة منقول أو عقار، خلال مدة معينة في مقابل أجرة محددة، يلتزم الطرف الآخر بدفعها له.",
  "628": "يتم الكراء بتراضي الطرفين على الشيء وعلى الأجرة وعلى غير ذلك مما عسى أن يتفقا عليه من شروط في العقد.",
  "629": "ومع ذلك، يلزم أن يثبت كراء العقارات والحقوق العقارية بالكتابة، إذا عقدت لأكثر من سنة، فإن لم يوجد محرر مكتوب، اعتبر الكراء قد أجري لمدة غير معينة.\nكراء العقارات لمدة تزيد على سنة لا يكون له أثر في مواجهة الغير ما لم يكن مسجلا وفقا لما يقضي به القانون.",
  "630": "من لم يكن لهم على الشيء إلا حق شخصي في الاستعمال أو السكنى أو حق في حبسه أو رهن حيازي على منقول لم يجز لهم إكراؤه.",
  "631": "لا يصح أن يكون الشيء المكترى مما يهلك بالاستعمال، ما لم يكن القصد من كرائه مجرد إظهاره أو عرضه. ولكن يجوز كراء الأشياء التي تتعيب بالاستعمال.",
  "632": "تطبق الفصول 484 و485 و487 المتعلقة بمحل البيع على الكراء.",
  "633": "يجب أن تكون الأجرة معينة. ويسوغ أن تكون نقودا أو منتجات أو أطعمة أو أي منقولات أخرى بشرط أن تكون محددة بالنسبة إلى مقدارها وصنفها ويسوغ أيضا أن تكون الأجرة حصة شائعة في منتجات الشيء المكترى.\nويسوغ، في كراء الأراضي الزراعية، اشتراط قيام المستأجر، زيادة على دفع مبلغ محدد من النقود أو نصيب معلوم من الغلة، بإجراء أعمال معينة على اعتبار أنها تكون جزءا من الأجرة.",
  "634": "إذا لم يحدد المتعاقدان الأجرة، افترض فيهما أنهما قد قبلا أجرة المثل في مكان العقد، وإذا كانت ثمة تعريفة رسمية، افترض في المتعاقدين أنهما قد ارتضيا التعاقد على أساسها.",
  "635": "يتحمل المكري بالتزامين أساسيين:\nأولا - الالتزام بتسليم الشيء المكترى للمكتري؛\nثانيا - الالتزام بالضمان.",
  "636": "تسليم الشيء المكترى ينظم بمقتضى الأحكام المقررة لتسليم الشيء المبيع.",
  "637": "مصروفات التسليم على المكري.\nيتحمل كل من المتعاقدين مصروفات الحجج التي تسلم له كما يتحمل المكتري مصروفات رفع الشيء المكترى وتسلمه.\nوكل ذلك، ما لم يجر العرف[162] أو يقضي الاتفاق بخلافه.",
  "638": "يلتزم المكري بتسليم العين وملحقاتها، وبصيانتها أثناء مدة الإيجار في حالة تصلح معها لأداء الغرض الذي خصصت له وفقا لطبيعتها ما لم يشترط الطرفان غير ذلك، وفي كراء العقارات تقع الإصلاحات البسيطة على المكتري إذا قضى عرف[163] المكان بذلك.\nوإذا ثبت على المكري المَطْـل في إجراء الإصلاحات المكلف بها حق للمكتري إجباره على إجرائها قضاء. فإن لم يجرها المكري، ساغ للمكتري أن يستأذن المحكمة في إجرائها بنفسه وفي أن يخصم قيمتها من الأجرة.",
  "639": "في كراء العقارات، لا يلزم المكتري بإصلاحات ... [164] الصيانة البسيطة، إلا إذا كلف بها بمقتضى العقد أو العرف[165]، وهذه الإصلاحات هي التي تجرى:\nلبلاط الغرف وزليجها، إذا لم يتكسر منه إلا بعض وحداته؛\nللألواح الزجاجية، ما لم يكن تكسرها ناشئا عن البرد وغيره من النوازل الاستثنائية ونوازل القوة القاهرة التي لم يتسبب خطأ المكتري في حدوثها؛\nللأبواب والنوافذ والألواح المعدة لغلق الحوانيت والمفصلات والترابيس والأقفال.\nأما تبييض الغرف وإعادة طلائها واستبدال ما بلي من الأوراق الملصقة بجدرانها والأعمال اللازمة للسطوح ولو كانت مجرد أعمال الطلاء أو التبييض فتقع على عاتق المكري.",
  "640": "لا يتحمل المكتري أي شيء من إصلاحات الصيانة المعتبرة بسيطة[166] إذا تسبب عن القدم أو القوة القاهرة أو خطأ في البناء أو عن فعل المكري.",
  "641": "كنس الآبار والمراحيض ومجاري المياه على المكري، ما لم يقض العقد أو العرف بخلاف ذلك.",
  "642": "يلتزم المكري بدفع الضرائب وغيرها من التكاليف المفروضة على العين المكتراة، ما لم يقض العقد أو العرف[167] بخلاف ذلك.",
  "643": "الضمان الذي يلتزم به المكري للمكتري يرد على أمرين:\nأولا - الانتفاع بالشيء المكترى وحيازته بلا معارض؛\nثانيا - استحقاق الشيء والعيوب التي تشوبه.\nويثبت هذا الضمان بقوة القانون، وإن لم يشترط، ولا يحول حسن نية المكري دون قيامه.",
  "644": "الالتزام بالضمان، يقتضي، بالنسبة إلى المكري، التزامه بالامتناع عن كل ما يؤدي إلى تعكير صفو حيازة المكتري، أو إلى حرمانه من المزايا التي كان من حقه أن يعول عليها بحسب ما أعد له الشيء المكترى والحالة التي كان عليها عند العقد.\nوفي هذا المجال، يسأل المكري ليس فقط عن فعله وفعل أتباعه بل أيضا عن أفعال الانتفاع التي يجريها المكترون الآخرون أو غيرهم ممن تلقوا الحق عنه.",
  "645": "ومع ذلك، يحق للمكري أن يجري، برغم معارضة المكتري، الإصلاحات المستعجلة التي لا تحتمل التأخير إلى نهاية العقد. ولكن إذا ترتب على إجراء هذه الإصلاحات أن حرم المكتري من استعمال الشيء كله أو من جزء كبير منه لأكثر من ثلاثة أيام، كان له أن يطلب فسخ العقد أو إنقاص الكراء بما يتناسب مع المدة التي حرم خلالها من الشيء.\nوعلى المكري أن يثبت حالة الاستعجال في الإصلاحات وأن يخطر بها المكتري فإن لم يفعل، أمكن تحميله التعويضات عن الأضرار الناشئة عن عدم الإخطار.",
  "646": "ويلتزم المكري بقوة القانون أيضا بالضمان للمكتري في حالة التشويش أو الاستحقاق الذي قد يتأذى منه في كل الشيء المكترى أو بعضه، نتيجة دعوى متعلقة إما بحق الملكية أو بحق عيني آخر عليه.\nويطبق في هذه الحالة الفصلان 534 و537.",
  "647": "في الحالات المنصوص عليها في الفصلين 644 و645 السابقين يجوز للمكتري أن يطلب إما فسخ العقد أو إنقاص الكراء، وفقا لمقتضيات الحال.\nوتطبق أحكام الفصول 537 و542 إلى 545 مع دخول الغاية على الحالات المنصوص عليها في هذا الفصل.",
  "648": "إذا رفعت الدعوى على المكتري، من أجل الحكم عليه، بالتخلي عن العين كلها أو بعضها، أو بتحمل مباشرة[168] أي ارتفاق عليها لزمه أن يخطر بها المكري فورا. ويجب عليه، في فترة الانتظار ألا يتنازل عن أي جزء من العين التي في يده. ويلزم في جميع الحالات، إخراجه من الدعوى، بتعيينه الشخص الذي يحوز العين لحسابه. وعندئذ لا تسوغ مباشرة الدعوى إلا في مواجهة المكري. ولكن يجوز للمكتري التدخل فيها.",
  "649": "لا يلتزم المكري بأن يضمن للمكتري مجرد التشويش المادي الواقع من الغير في انتفاعه بالعين المكتراة بدون أن يدعي ذلك الغير أي حق عليها، مادام المكري لم يتسبب بفعله في وقوعه. وللمكتري في هذه الحالة أن يقاضي الغير باسمه الشخصي.",
  "650": "إلا أنه إذا بلغ التشويش المادي من الجسامة بحيث يحرم المكتري من الانتفاع بالعين المكتراة، فإنه يسوغ له طلب إنقاص في الكراء متناسب مع ذلك التشويش.\nوعليه في هذه الحالة أن يقيم الدليل على:\nأ - أن التشويش قد وقع؛\nب - أن هذا التشويش يتنافى مع استمرار انتفاعه.",
  "651": "إذا انتزعت العين المكتراة من المكتري بفعل السلطة أو من أجل المصلحة العامة، ساغ له أن يطلب فسخ العقد ولا يلتزم بدفع الكراء، إلا بقدر انتفاعه. إلا أنه إذا لم يقع فعل السلطة أو نزع الملكية إلا على جزء من العين، فإنه لا يكون للمكتري إلا الحق في إنقاص الكراء، ويجوز له أن يطلب الفسخ إذا أصبحت العين، بسبب النقص الذي اعتراها، غير صالحة للاستعمال فيما أعدت له، أو إذا نقص الانتفاع بالجزء الباقي منها إلى حد كبير.\nوفي هذه الحالة تطبق أحكام الفصل 546.",
  "652": "أعمال الإدارة العامة التي تتم وفقا لما يقضي به القانون والتي يترتب عنها نقص كبير في انتفاع المكتري، كالأشغال التي تنفذها الإدارة والقرارات التي تصدرها، تبيح له أن يطلب، على حسب الأحوال، إما فسخ العقد أو إنقاصا في الكراء متناسبا مع ذلك النقص. ويجوز أن يترتب على المكري التعويض عنها، إذا كانت ناتجة بسبب فعل أو خطأ يعزى إليه. وكل ذلك ما لم يتفق الطرفان على خلافه.",
  "653": "دعاوى المكتري ضد المكري بموجب أحكام الفصول 644 إلى 652 مع دخول الغاية تتقادم بانتهاء مدة عقد الكراء.",
  "654": "يضمن المكري للمكتري كل عيوب الشيء المكترى التي من شأنها أن تنقص من الانتفاع به إلى حد ملموس أو تجعله غير صالح لاستعماله في الغرض الذي أعد له بحسب طبيعته أو بمقتضى العقد. ويضمن له أيضا خلو الشيء من الصفات التي وعد بها صراحة، أو تلك التي يتطلبها الغرض الذي أعد له.\nالعيوب التي لا تحول دون الانتفاع بالشيء المكترى أو العيوب التي لا تلحق به إلا نقصا تافها، لا تخول المكتري حق الرجوع بالضمان ويطبق نفس الحكم على العيوب التي جرى العرف[169] بالتسامح فيها.",
  "655": "عندما يكون للضمان محل، يحق للمكتري أن يطلب فسخ العقد أو إنقاص الكراء. ويثبت له الحق في التعويض في الحالات المذكورة في الفصل 556.\nتطبق أحكام الفصول 558، 559، 560 على الحالة المنصوص عليها في هذا الفصل.",
  "656": "لا يضمن المكري عيوب الشيء المكترى التي كان يمكن التحقق منها بسهولة وذلك ما لم يكن قد صرح بعدم وجودها. وهو لا يسأل أيضا عن أي ضمان:\nأ - إذا كان المكتري يعلم، عند إبرام العقد، عيوب الشيء المكترى أو خلوه من الصفات المطلوبة فيه؛\nب - إذا كان قد حصل التصريح للمكتري بالعيوب؛\nج - إذا اشترط المكري أنه لا يلتزم بأي ضمان.",
  "657": "ومع ذلك، إذا كان من شأن عيب الشيء المكترى أن يهدد جديا صحة أو حياة من يسكنونه، فإنه يسوغ للمكتري دائما أن يطلب فسخ العقد ولو كان عند إبرامه عالما بالعيب، أو كان قد تنازل عن حقه في طلب الفسخ.",
  "658": "يطبق حكم الفصل 574 على الكراء.",
  "659": "إذا هلكت العين المكتراة أو تعيبت أو تغيرت كليا أو جزئيا بحيث أصبحت غير صالحة للاستعمال في الغرض الذي اكتريت من أجله، وذلك دون خطأ أي واحد من المتعاقدين، فإن عقد الكراء ينفسخ، من غير أن يكون لأحدهما على الآخر أي حق في التعويض، ولا يلزم المكتري من الكراء إلا بقدر انتفاعه.\nوكل شرط يخالف ذلك يكون عديم الأثر.",
  "660": "إذا لم تهلك العين المكتراة أو لم تتعيب إلا جزئيا، بحيث تبقى صالحة للاستعمال في الغرض الذي اكتريت من أجله، أو تبقى صالحة له جزئيا لم يكن للمكتري إلا حق إنقاص الكراء بقدر ما نقص من انتفاعه.",
  "661": "تطبق أحكام الفصلين 659 و660 على الحالة التي يتخلف فيها بعد العقد وبدون خطأ أي واحد من المتعاقدين، الوصف الموعود به من المكري أو الذي يقتضيه إعداد العين المكتراة.",
  "662": "دعاوى المكتري على المكري بموجب الفصول 654 و660 و661 لا يمكن رفعها بشكل مفيد ابتداء من الوقت الذي ينتهي فيه عقد الكراء.",
  "663": "يتحمل المكتري بالتزامين أساسيين:\nأ - أن يدفع الكراء؛\nب - أن يحافظ على الشيء المكترى وأن يستعمله بدون إفراط أو إساءة وفقا لإعداده الطبيعي أو لما خصص له بمقتضى العقد.",
  "664": "يلتزم المكتري بدفع الكراء في الأجل الذي يحدده العقد، فإن لم يحدد العقد لدفعه أجلا، التزم المكتري بدفعه في الأجل الذي يحدده العرف[170] المحلي فإن لم يحدد العرف[171] المحلي بدوره أجلا، التزم المكتري بدفعه في نهاية الانتفاع.\nويسوغ اشتراط دفع الكراء مقدما، ويتحمل المكتري مصروفات الوفاء.",
  "665": "كل حجة تتضمن إبراء أو توصيلا بكراء لم يستحق بعد لمدة تتجاوز سنة لا يحتج بها في مواجهة الغير، إلا إذا كانت ثابتة التاريخ.",
  "666": "يدفع الكراء بالنسبة إلى العقارات في المكان الذي توجد فيه العين المكتراة، وبالنسبة إلى المنقولات في مكان إبرام العقد.\nوذلك كله ما لم يشترط خلافه.",
  "667": "يلتزم المكتري بدفع الكراء كاملا وذلك بشرط أن يكون المكري قد وضع العين تحت تصرفه خلال الوقت وبالكيفية المحددين بمقتضى العقد أو العرف[172] ولو لم يستطع الانتفاع بالعين المكتراة أو لم ينتفع بها إلا انتفاعا محدودا من جراء خطإه أو لسبب يرجع إلى شخصه.\nإلا أنه إذا كان المكري قد تصرف في العين أو انتفع بها على نحو آخر، خلال الوقت الذي تعذر فيه على المكتري الانتفاع بها فإنه يجب عليه أن يراعي المنافع التي استخلصها منها وأن يخصم قيمتها مما يجب له على المكتري.",
  "668": "للمكتري الحق في أن يكري تحت يده ما اكتراه وأن يتنازل عن عقد الكراء لغيره، بالنسبة إلى الشيء كله أو بعضه إلا إذا حجر عليه ذلك في العقد أو اقتضته طبيعة ما اكتراه، ويجب أن يفهم المنع من الكراء للغير على إطلاقه، بحيث لا يسوغ الكراء للغير ولو جزئيا، كما لا يسوغ التنازل عن الانتفاع ولو على سبيل التبرع[173].",
  "669": "لا يسوغ للمكتري أن يتنازل أو يكري تحت يده ما اكتراه من أجل استعماله في غير ما أعد له أو فيما هو أثقل مما حدده العقد أو تقتضيه طبيعة الشيء.\nوعند الاختلاف وعدم وجود حجج يجب العمل بما فيه صالح المكتري[174].",
  "670": "المكتري ضامن لمن تنازل له عن كراء الشيء أو أكراه له تحت يده. ويبقى هو نفسه متحملا، في مواجهة المكري بكل الالتزامات الناشئة من العقد ولا يبقى ملتزما:\nأولا - إذا قبض المكري مباشرة الكراء من يد المكتري الفرعي أو المتنازل له عن الكراء، من غير أن يجري أي تحفظ ضد المكتري الأصلي؛\nثانيا - إذا قبل المكري صراحة عقد الكراء تحت اليد أو التنازل عن الكراء من غير أن يجري أي تحفظ ضد المكتري الأصلي.",
  "671": "المكتري الفرعي ملتزم مباشرة تجاه المكري، بقدر ما عليه للمكتري الأصلي، في وقت الإنذار الموجه إليه. ولا يسوغ له التمسك بالمدفوعات المسبقة التي يؤديها للمكتري الأصلي إلا:\nأولا - إذا كانت هذه المدفوعات مطابقة لعرف[175] المكان؛\nثانيا - إذا كانت هذه المدفوعات محررة في حجة ثابتة التاريخ.",
  "672": "للمكري حق الدعوى المباشرة في مواجهة المكتري الفرعي، في جميع الحالات التي تكون له في مواجهة المكتري الأصلي، وذلك دون إخلال بحقه في الرجوع على هذا الأخير. ويسوغ للمكتري الأصلي دائما التدخل في الدعوى. وللمكري أيضا دعوى مباشرة ضد المكتري الفرعي لإجباره على رد العين عند انقضاء الأجل المحدد.",
  "673": "تطبق في التنازل عن الكراء القواعد المقررة في باب حوالة الحقوق. وهذا التنازل يترتب عليه حلول المتنازل له محل المتنازل في الحقوق والالتزامات الناشئة من عقد الكراء.",
  "674": "يجب على المكتري، أن يخطر المالك بدون إبطاء بكل الوقائع التي تقتضي تدخله سواء تعلقت بالإصلاحات المستعجلة أم باكتشاف عيوب غير متوقعة، أم بحصول غصب، أم بادعاء الملكية، أو غيرها من الحقوق العينية أم بالأضرار الحاصلة بفعل الغير. وإن لم يقم بذلك الإخطار وجب عليه التعويض.",
  "675": "يلتزم المكتري برد العين، عند انقضاء الأجل المحدد. فإذا احتفظ بها بعده، التزم بالكراء على حسب تقدير أهل الخبرة عن المدة الزائدة التي احتفظ بها خلالها. ويسأل عن كل الأضرار التي تلحق العين أثناء هذه المدة ولوحصلت نتيجة حادث فجائي. وفي هذه الحالة لا يلتزم إلا بالتعويض دون الكراء.",
  "676": "إذا حررت بين المكري والمكتري، قائمة تثبت حالة العين المكتراة أو وصفها وجب على المكتري أن يرد العين بالحالة التي تسلمها عليها.",
  "677": "إذا لم تحرر قائمة تثبت حالة العين المكتراة أو وصفها، افترض في المكتري أنه تسلمها في حالة حسنة.",
  "678": "يسأل المكتري عن هلاك العين أو تعيبها الحاصل بفعله أو بإساءته استعمالها. ويسأل مكتري الفندق أو أي محل عام آخر أيضا عن فعل النزلاء أو الزبناء الذين يستقبلهم في ذلك المحل.",
  "679": "لا يسأل المكتري عن الهلاك أو التعيب الحاصل:\nأولا - من الاستعمال المألوف والعادي للشيء؛\nثانيا - نتيجة حادث فجائي أو قوة قاهرة لا يعزى أي منهما إلى خطإه؛\nثالثا - نتيجة حالة القدم أو عيب في البناء أو بسبب عدم إجراء الإصلاحات التي يتحمل بها المكري.",
  "680": "يجب أن يحصل رد الشيء المكترى في مكان العقد. ومصروفات الرد تقع على عاتق المكتري، ما لم يشترط غيره أو يقضي العرف[176] بخلافه.",
  "681": "لا يسوغ للمكتري أن يحبس الشيء المكترى لا من أجل المصروفات التي أنفقها عليه، ولا من أجل غيرها من الحقوق التي قد تثبت له في مواجهة المكري.",
  "682": "يلتزم المكري بأن يدفع للمكتري كل المصروفات الضرورية التي أنفقها من أجل المحافظة على الشيء، فيما عدا المصروفات البسيطة. ويجب عليه أيضا أن يدفع المصروفات النافعة التي أنفقها بغير إذنه، في حدود قيمة المواد والمغروسات وأجرة العمل، بدون اعتبار لما ترتب عليها من زيادة في قيمة الشيء.\nولا يلتزم المكري بدفع مصروفات الزخرف والترف. ولكن يسوغ للمكتري أن يزيل التحسينات التي أجراها، ما لم يؤد ذلك إلى ضرر.",
  "683": "إذا أذن المكري للمكتري في إجراء تحسينات، التزم بأن يدفع له قيمتها في حدود ما أنفقه.\nوعلى المكتري أن يثبت الإذن الذي يدعيه.",
  "684": "للمكري حق الحبس، ضمانا للكراء الحال والذي يحل خلال السنة الجارية، على الأثاث وغيرها من الأشياء المنقولة الموجودة في المحلات المكتراة، والمملوكة إما للمكتري أو للمكتري الفرعي، أو حتى للغير.\nوله أن يعترض على نقل هذه الأشياء، بالالتجاء إلى السلطة المختصة. ويسوغ له أن يستردها، إذا نقلت بغير علمه أو برغم معارضته بقصد إعادتها إلى المكان الذي كانت موجودة فيه، أو وضعها في مستودع آخر.\nولا يسوغ للمكري مباشرة هذا الحق في الحبس أو في الاسترداد إلا في حدود القيمة اللازمة لضمانه. وليس له حق التتبع إذا كانت الأشياء الباقية في المحلات المكتراة تكفي لتأمين حقوقه.\nو لا تجوز مباشرة حق الاسترداد بعد خمسة عشر يوما من وقت علم المكري بحصول النقل.\nو لا تجوز مباشرة حق الحبس أو الاسترداد:\nأ - على الأشياء التي لا يمكن إجراء حجز المنقول عليها؛\nب - على الأشياء المسروقة أو الضائعة؛\nج - على الأشياء المملوكة للغير، إذا كان المكري يعلم عند إدخالها إلى المحلات المكتراة، بأنها مملوكة لذلك الغير.",
  "685": "حق الحبس الثابت للمكري يمتد إلى الأمتعة التي يضعها المكتري الفرعي في العين، في حدود حقوق المكتري الأصلي على المكتري الفرعي ومن غير أن يكون له التمسك بالمدفوعات المسبقة الحاصلة منه للمكتري الأصلي فيما عدا الاستثناءات المنصوص عليها في الفصل 671.",
  "686": "دعاوى المكري ضد المكتري بموجب الفصول 670 و672 و674 إلى 676 و678 تتقادم بمضي ستة أشهر من وقت تسلمه الشيء المكترى.",
  "687": "كراء الأشياء ينقضي بقوة القانون عند انتهاء المدة التي حددها له المتعاقدان من غير ضرورة لإعطاء تنبيه بالإخلاء، وذلك ما لم يقض الاتفاق بغيره ومع عدم الإخلال بالقواعد الخاصة بكراء الأراضي الزراعية.",
  "688": "إذا لم تحدد للكراء مدة، اعتبر مبرما على أساس السنة أو نصف السنة، أو الشهر أو الأسبوع أو اليوم، بحسب ما إذا كانت الأجرة قد حددت باعتبار كذا في السنة أو نصف السنة أو الشهر إلخ... وينتهي العقد بانقضاء كل من المدد السابقة، من غير ضرورة للتنبيه بالإخلاء، وذلك ما لم يوجد عرف[178] يخالفه.",
  "689": "إذا أبرم الكراء لمدة محددة، ثم انتهت، وظل المكتري واضعا يده على العين، فإنه يتجدد بنفس الشروط ولنفس المدة. وإذا أبرم الكراء من غير أن تحدد له مدة، ساغ لكل من عاقديه أن يفسخه، ويثبت مع ذلك للمكتري الحق في الأجل الذي يحدده العرف[179] المحلي لإخلاء المكان.",
  "690": "استمرار المكتري في الانتفاع بالعين لا يؤدي إلى التجديد الضمني للكراء إذا كان قد حصل تنبيه بالإخلاء أو أي عمل يعادله يدل على رغبة أحد المتعاقدين في عدم تجديد العقد.",
  "691": "في الحالة المذكورة في الفصل 689، لا تمتد الكفالة التي قدمت ضمانا للعقد القديم إلى الالتزامات الناشئة من التجديد الضمني. ولكن الرهون الحيازية وغيرها من التأمينات تبقى.",
  "692": "للمكري فسخ الكراء مع حفظ حقه في التعويض إن اقتضى الأمر:\nأولا - إذا استعمل المكتري الشيء المكترى في غير ما أعد له بحسب طبيعته أو بمقتضى الاتفاق؛\nثانيا - إذا أهمل الشيء المكترى على نحو يسبب له ضررا كبيرا؛\nثالثا - إذا لم تؤد الكراء الذي حل أجل أدائه.",
  "693": "لا يحق للمكري فسخ الكراء، ولو صرح برغبته في شغل الدار المكتراة بنفسه.",
  "694": "لا يفسخ عقد الكراء بالتفويت الاختياري أو الجبري للعين المكتراة. ويحل المالك الجديد محل من تلقى الملك عنه في كل حقوقه والتزاماته الناتجة من الكراء القائم، بشرط أن يكون هذا الكراء قد أجري بدون غش، وأن يكون له تاريخ سابق على التفويت.",
  "695": "إذا لم يكن الكراء واردا في حجة ثابتة التاريخ، ساغ لمكتسب الملكية إخراج المكتري، بشرط أن يوجه له تنبيها بالإخلاء في المواعيد التي يقضي بها العرف[180].",
  "696": "إذا لم ينفذ المالك الجديد الالتزامات التي يفرضها الكراء على المكري كان للمكتري أن يرجع عليه وعلى من باع له متضامنين، من أجل كل ما عساه أن يتقرر له من تعويضات بمقتضى القانون.",
  "697": "إذا استحق الشيء المكترى، ثبت للمستحق الخيار بين أن يحتفظ بالكراء القائم وبين أن يفسخه. إلا أنه يجب عليه، في الحالة الأخيرة، مراعاة المواعيد المقررة للتنبيه بالإخلاء، إذا كان المكتري حسن النية. ولا يكون للمكتري الرجوع من أجل الكراء والتعويضات المستحقة له إلا على المكري إذا كان لهذا الرجوع محل.",
  "698": "لا يفسخ الكراء بموت المكتري ولا بموت المكري إلا أنه:\nأولا - الكراء الذي يبرمه المستحق في ملك محبس ينفسخ بموته؛\nثانيا - الكراء الذي يبرمه من بيده الشيء بدون موجب ينفسخ بموته.",
  "699": "ينتج عن فسخ الكراء الأصلي فسخ الكراء الفرعي المعقود من المكتري مع استثناء الحالتين المذكورتين في البندين ( أولا وثانيا ) من الفصل 670.",
  "700": "يخضع كراء الأراضي الفلاحية للقواعد العامة السابقة، مع استثناء الأحكام الآتية:",
  "701": "يجوز إبرام كراء الأراضي الفلاحية لمدة أربعين سنة، فإن أبرم لمدة أطول ساغ لكل من المتعاقدين فسخه بعد انتهاء الأربعين سنة.\nويبدأ كراء الأراضي الفلاحية في 13 من سبتمبر من التقويم الغريغوري[181] ما لم يحدد المتعاقدان تاريخا آخر.",
  "702": "يجب أن يحدد عقد الكراء نوع الزراعة أو المحاصيل التي يقوم عليها الاستغلال. فإن سكت العقد، اعتبر المكتري مأذونا في زرع كل ما يزرع في الأراضي التي من نوع الأرض المكتراة، على نحو ما هو مذكور في الفصل 704.",
  "703": "إذا شمل الكراء آلات أو ماشية أو مواد فلاحية كالعلف والسماد، وجب على كل من المتعاقدين أن يسلم الآخر عنها إحصاء مضبوطا وموقعا عليه منه. كما يجب على المتعاقدين أن يعملا على تقويم مشترك لتلك الأشياء.",
  "704": "على المكتري أن ينتفع بالعين المكتراة، على النحو المحدد في العقد. وليس له أن ينتفع بها على نحو يضر بالمالك. وليس له أن يجري في استغلالها تغييرات من شأنها أن تحدث تأثيرا ضارا يستمر حتى بعد انتهاء الكراء، ما لم يؤذن له بها صراحة.",
  "705": "ليس للمكتري الحق في نتاج الحيوانات ولا في الزيادات التي تطرأ على الشيء خلال مدة العقد.",
  "706": "ليس للمكتري حق فيما يتحصل من صيد البر والماء، ما لم تكن العين قد خصصت لاستعمالها في هذا الغرض. إلا أن له الحق في منع أي شخص كان، حتى المكري نفسه، من دخول المحلات المكتراة بغرض الصيد فيها.",
  "707": "جميع الأشغال اللازمة للانتفاع بالشيء، كشق الطرق وصيانتها، وإنشاء وصيانة الممرات والحواجز، والإصلاحات البسيطة للمباني الفلاحية والمطامر لا تقع على عاتق المكتري ما لم يحمله بها العقد أو العرف[182] المحلي. وفي هذه الحالة الأخيرة يلتزم المكتري بإجراء الأعمال على نفقته ومن غير أن يكون له حق التعويض عنها، ويسأل تجاه المكري عن الأضرار الناتجة عن عدم القيام بها.\nالأعمال المتعلقة بتشييد المباني وغيرها من توابع الأرض الفلاحية المكتراة وبإجراء ما يلزمها من الإصلاحات الكبرى تقع على عاتق المكري. كما تقع على عاتقه أيضا الإصلاحات اللازمة للآبار والقنوات ومجاري المياه والخزانات. وإذا ماطل المكري في إجراء ما يلزمه من إصلاحات، طبقت أحكام الفصل 638.",
  "708": "إذا أعطي في كراء الأراضي الفلاحية للعين مضمون يزيد أو يقل عما هو ثابت لها في حقيقة الواقع، كان هناك محل إما لزيادة الأجرة أو لإنقاصها أو لفسخ العقد، على حسب الأحوال، ووفقا للقواعد المقررة في باب البيع. وتتقادم هذه الدعوى بفوات سنة ابتداء من العقد، ما لم يكن قد حدد لبدء الانتفاع تاريخ لاحق، وفي هذه الحالة يبدأ سريان الميعاد من هذا التاريخ الأخير.",
  "709": "إذا منع المكتري من حرث الأرض أو زرعها بسبب حادث فجائي أو قوة قاهرة، كان له حق الإعفاء من الكراء أو استرداده من المكري، إذا كان قد سبقه له. وذلك بشرط:\nأولا: ألا يكون الحادث الفجائي أو القوة القاهرة، قد حدث نتيجة خطإه؛\nثانيا: وألا يكون متعلقا بشخصه.",
  "710": "للمكتري حق الإعفاء من الكراء أو استرداده، إذا زرع الأرض ثم هلك كل الزرع نتيجة حادث فجائي، أو قوة قاهرة لا يعزيان إلى خطإه.\nوإذا كان هلاك الزرع جزئيا، لم يكن هناك محل لتخفيض الكراء أو لاسترداده بما يتناسب مع الجزء الهالك، إلا إذا تجاوز هذا الجزء النصف.\nولا يكون محل للإعفاء من الكراء أو لتخفيضه، إذا كان المكتري قد عوض عن الخسارة التي لحقته، إما من محدث الضرر وإما من إحدى شركات التأمين.",
  "711": "لا محل للإعفاء من الكراء ولا لتخفيضه:\nأولا: إذا حدث الهلاك بعد فصل المحصول عن الأرض؛\nثانيا: إذا كان سبب الهلاك موجودا عند إبرام العقد، وكان المكتري حينئذ على علم به، وكان من طبيعته أن يولد الأمل في التمكن من إيقافه.",
  "712": "يبطل كل شرط من شأنه أن يحمل المكتري تبعة الحوادث الفجائية، أو يلزمه بدفع الكراء ولو لم ينتفع بالعين لأحد الأسباب المذكورة في الفصلين 709 و710.",
  "713": "لمكري الأرض الفلاحية أن يطلب الفسخ:\nأولا: إذا لم يجهزها المكتري بما يلزم لاستغلالها من الآلات والماشية؛\nثانيا: إذا ترك المكتري فلاحتها، أو إذا لم يعتن بفلاحتها عناية العاقل بملكه؛\nثالثا: إذا استعملها المكتري في غير الغرض الذي أعدت له بحسب طبيعتها أو بمقتضى العقد، وعلى العموم إذا لم ينفذ شروط عقد الكراء بحيث يؤدي ذلك إلى الإضرار بالمكري.\nوفي كل ما سبق يثبت طلب الفسخ للمكري، مع حفظ حقه في التعويض إن كان له محل.",
  "714": "كراء الأراضي الفلاحية ينتهي بقوة القانون بانقضاء المدة التي أبرم لها.\nفإن لم يتفق فيه على مدة، اعتبر أنه قد أبرم إلى الوقت اللازم لقيام المكتري بجني كل الثمار التي تغلها العين المكتراة.\nيجب إعطاء التنبيه بالإخلاء قبل فوات السنة الجارية بستة أشهر على الأقل.\nكراء الأراضي المعدة للفلاحة التي تستغل بطونا بحسب فصول السنة ينتهي بانتهاء آخر بطن.\nفي كراء أرض السقي، السنة الفلاحية اثنا عشر شهرا. وإذا وجد في الأرض، عند انتهاء السنة زرع أخضر، وجب على المكري أن يسمح للمكتري الذي بذره في الوقت المناسب الذي كان من شأنه في الظروف العادية أن يمكنه من جني المحصول قبل انتهاء الكراء، بالبقاء فيها حتى يتمكن من جني المحصول وله في مقابل ذلك حق في الكراء عن المدة الجديدة.",
  "715": "إذا بقي المكتري في العين بعد انتهاء مدة الكراء وتركه المكري فيها، اعتبر الكراء متجددا لنفس المدة، إذا كان قد أبرم لمدة محددة، ولممدة سنة فلاحية أي حتى حصاد المحصول القادم، إذا كان قد أبرم لمدة غير محددة.",
  "716": "لمكتري الأرض الفلاحية التي لم ينبت زرعها عند نهاية كرائه، إذا قام بإثبات حالته وقتذاك، الحق في أن يبقى فيها، على أن يدفع للمكري كراء مساويا للكراء الذي حدده العقد، وذلك مع استثناء الحالة التي يعزى إليه فيها الغش أو الخطأ.",
  "717": "إذا وجدت عند انتهاء الكراء الوارد على أرض السقي، ثمار متصلة بأصولها أو خضر لمَّا تنضج، وكان المكتري قد تأخر في البذر بحيث لم يبذر في الوقت المناسب الذي من شأنه أن يمكنه، في الظروف العادية من الحصاد قبل نهاية الكراء، فإنه يثبت للمكري الخيار بين أن يجدد الكراء بنفس الثمن وبين أن يفسخه مع دفعه للمكتري ثلاثة أرباع كل من قيمة البذور وأجرة العمل.",
  "718": "على المكتري الخارج أن يمتنع عن كل ما من شأنه أن ينقص أو يؤخر من انتفاع من يخلفه في استغلال العين ويجب عليه الامتناع عن إجراء أي حرث جديد قبل نهاية كرائه بشهرين. كما يلزمه إذا كان قد حصد زرعه أن يمكن المكتري الجديد من إجراء الأشغال الإعدادية في الوقت المناسب. ويطبق كل ما سبق ما لم يقض العرف[183] المحلي بخلافه.",
  "719": "على المكتري الخارج أن يترك لمن يخلفه، قبل أن يبدأ انتفاعه ببعض الوقت ما يناسب من المساكن وغيرها من التسهيلات اللازمة للقيام بما تتطلبه السنة القادمة من أشغال. كما يجب على المكتري الداخل أن يترك للخارج المساكن المناسبة وأن يؤدي التسهيلات اللازمة لاستهلاك التبن ولإجراء ما بقي من حصاد.\nوفي هذه الحالة وتلك، يطبق العرف[184] المحلي.",
  "720": "على المكتري الخارج، إذا كان عند بدء انتفاعه قد تسلم قدرا من التبن والعلف والسماد، أن يترك في العين قدرا مماثلا مما تسلمه منها. وليس له أن يتحلل من هذا الالتزام بادعاء الحادث الفجائي. وحتى لو لم يكن المكتري قد تسلم الأشياء السابقة، يجوز للمكري أن يحتفظ منها بقدر كاف، مع دفع قيمتها مقدرة بسعر اليوم. ويطبق في هذا أيضا العرف[185] المحلي.",
  "721": "على المكتري أن يرد عند نهاية الكراء الأشياء التي سلمت له بمقتضى قائمة الإحصاء. وهو يسأل عن هذه الأشياء، مع استثناء ما يحصل لها نتيجة القوة القاهرة التي لا تعزى إلى خطإه، والعيب الناتج من استعمالها على نحو عاد مألوف.\nوإذا كان المكتري، خلال مدة الكراء، قد استبدل بالأشياء الهالكة أشياء أخرى مكانها، أو أصلح ما تعيب، حق له أن يسترد ما أنفقه ما لم يكن هناك خطأ يعزى إليه.",
  "722": "إذا أكمل المكتري من ماله الأدوات المخصصة للاستغلال، بأن أضاف إليها أدوات أخرى لم تذكر في قائمة الإحصاء ثبت للمالك، عند نهاية الكراء الخيار بين أن يدفع له قيمة هذه الأدوات الأخيرة مقدرة على نحو ما يقرره أهل الخبرة، وبين أن يردها له في الحالة التي هي عليها.",
  "618-1": "يعتبر بيعا لعقار في طور الإنجاز كل اتفاق يلتزم البائع بمقتضاه بإنجاز عقار داخل أجل محدد كما يلتزم فيه المشتري بأداء الثمن تبعا لتقدم الأشغال. يحتفظ البائع بحقوقه وصلاحياته باعتباره صاحب المشروع إلى غاية انتهاء الأشغال.",
  "1-618": "يعتبر بيعا لعقار في طور الإنجاز كل اتفاق يلتزم البائع بمقتضاه بإنجاز عقار داخل أجل محدد كما يلتزم فيه المشتري بأداء الثمن تبعا لتقدم الأشغال.\nيحتفظ البائع بحقوقه وصلاحياته باعتباره صاحب المشروع إلى غاية انتهاء الأشغال.",
  "618-2": "يجب أن يحرر عقد البيع الابتدائي لعقار في طور الإنجاز، تحت طائلة البطلان، في محرر رسمي أو بمقتضى عقد عرفي ثابت التاريخ يتم تحريره من لدن مهني ينتمي إلى مهنة قانونية منظمة ومؤهلة لتحرير هذه العقود بمقتضى قوانينها الخاصة.",
  "2-618": "يجب أن يتم بيع العقار في طور الإنجاز سواء كان معدا للسكنى أو للاستعمال المهني أو التجاري أو الصناعي أو الحرفي من طرف الأشخاص الخاضعين للقانون العام أو الخاص طبقا لأحكام هذا الفرع.",
  "618-3": "يجب أن يتضمن العقد الابتدائي لبيع العقار في طور الإنجاز مجموعة من البيانات الأساسية تحت طائلة البطلان: هوية الأطراف، مراجع الرسم العقاري، المساحة التقريبية، ثمن البيع الإجمالي، وكيفية وتواريخ الأداء.",
  "3-618": "يجب أن يحرر عقد البيع الابتدائي للعقار في طور الإنجاز إما في محرر رسمي أو بموجب عقد ثابت التاريخ يتم تحريره من طرف مهني ينتمي إلى مهنة قانونية منظمة ويخول لها قانونها تحرير العقود وذلك تحت طائلة البطلان[154]..\nيحدد وزير العدل سنويا لائحة بأسماء المهنيين المقبولين لتحرير هذه العقود.\nيقيد باللائحة المحامون المقبولون للترافع أمام محكمة النقض[155] طبقا للفصل 34 من الظهير الشريف رقم 162-93-1 الصادر في 22 من ربيع الأول 1414 (10 سبتمبر 1993) المعتبر بمثابة قانون يتعلق بتنظيم مهنة المحاماة[156].\nيحدد نص تنظيمي شروط تقييد باقي المهنيين المقبولين لتحرير هذه العقود.\nيجب أن يتم توقيع العقد والتأشير على جميع صفحاته من الأطراف ومن الجهة التي حررته.\nيتم تصحيح الإمضاءات بالنسبة للعقود المحررة من طرف المحامي لدى رئيس كتابة الضبط للمحكمة الابتدائية التي يمارس المحامي بدائرتها.\nيجب أن يتضمن العقد على الخخصوص العناصر التالية:\n- هوية الأطراف المتعاقدة؛\n- الرسم العقاري الأصلي للعقار المحفظ موضوع البناء أو مراجع ملكية العقار غير المحفظ، مع تحديد الحقوق العينية والتحملات العقارية[157] الواردة على العقار وأي ارتفاق آخر عند الاقتضاء[158]؛\n- تاريخ ورقم رخصة البناء؛\n- وصف العقار محل البيع؛\n- ثمن البيع النهائي وكيفية الأداء؛\n- أجل التسليم؛\n- مراجع الضمانة البنكية أو أي ضمانة أخرى أو التأمين عند الاقتضاء.\nويجب أن يرفق هذا العقد:\n- بنسخ مطابقة لأصل التصاميم المعمارية بدون تغيير وتصاميم الإسمنت المسلح ونسخة من دفتر التحملات؛\n- بشهادة مسلمة من لدن المهندس المختص تثبت الانتهاء من أشغال الأساسات الأرضية للعقار.",
  "618-4": "لا يجوز للبائع مطالبة المشتري بأي مبالغ مالية قبل تحرير العقد الابتدائي للبيع وتوقيعه من الطرفين.",
  "4-618": "يجب على البائع أن يضع دفترا للتحملات يتعلق بالبناء ويتضمن مكونات المشروع وما أعد له ونوع الخدمات والتجهيزات التي يتوجب إنجازها وأجل الإنجاز والتسليم.\nيوقع البائع والمشتري على دفتر التحملات وتسلم نسخة للمشتري مشهود بمطابقتها لأصلها وبصحة إمضائه عليها.\nإذا كان العقار محفظا، تودع نسخ من هذا الدفتر ومن التصاميم المعمارية بدون تغيير وتصاميم الإسمنت المسلح ومن نظام الملكية المشتركة عند الاقتضاء بالمحافظة على الأملاك العقارية.\nوإذا كان العقار غير محفظ تسجل هذه النسخ بسجل خاص وتودع بكتابة الضبط لدى المحكمة الابتدائية التي يوجد بدائرتها العقار.",
  "618-5": "يتعين على البائع وضع دفتر تحملات خاص بالبناء يتضمن الخصائص التقنية والمواد المستعملة، وإيداعه بالمحافظة العقارية أو المصالح الجماعية المختصة.",
  "5-618": "لا يمكن إبرام العقد الابتدائي لبيع العقار في طور الإنجاز إلا بعد الانتهاء من أشغال الأساسات على مستوى الطابق الأرضي.",
  "618-6": "يؤدي المشتري قسطا من الثمن تبعا لتقدم الأشغال وفقا للجدولة الآتية: 10% عند إبرام العقد الابتدائي، 60% مقسمة على مراحل البناء، و30% عند تسليم المفاتيح وعقد البيع النهائي.",
  "6-618": "يؤدي المشتري قسطا من الثمن تبعا لتقدم الأشغال ما لم يتفق الأطراف على خلاف ذلك حسب المراحل التالية عند:\n- انتهاء الأشغال المتعلقة بالأساسات على مستوى الطابق الأرضي (السفلي)؛\n- انتهاء الأشغال الكبرى لمجموع العقار؛\n- الانتهاء من الأشغال النهائية.",
  "618-7": "يلتزم البائع بتقديم ضمانة بنكية أو تأمين مالي للمشتري يضمن استرداد المبالغ المدفوعة في حالة عدم تنفيذ البائع لالتزاماته أو توقفه عن البناء.",
  "7-618": "يتعهد البائع باحترام التصاميم الهندسية وأجل إنجاز البناء، وبصفة عامة باحترام شروط دفتر التحملات المشار إليه في الفصل 4-618 أعلاه.\nغير أنه، وبعد الموافقة المسبقة للمشتري، يمكن منح أجل إضافي للبائع لإنجاز العقار.",
  "618-8": "يجوز للمشتري إجراء تقييد احتياطي على الرسم العقاري لضمان حقوقه بمجرد توقيع العقد الابتدائي وحصول البناء على رخصة التأسيس.",
  "8-618": "يعد باطلا كل طلب أو قبول لأي أداء كيفما كان قبل التوقيع على عقد البيع الابتدائي.",
  "618-9": "إذا تأخر البائع في تسليم العقار داخل الأجل المحدد، لزمه تعويض المشتري عن التأخير بواقع 1% من المبالغ المدفوعة عن كل شهر تأخير.",
  "9-618": "على البائع أن يقيم لفائدة المشتري ضمانة بنكية أو أي ضمانة أخرى مماثلة وعند الاقتضاء تأمينا، وذلك لتمكين المشتري من استرجاع الأقساط المؤداة في حالة عدم تطبيق العقد.\nينتهي أجل هذه الضمانة بمجرد إبرام عقد البيع النهائي أو تقييده بالسجل العقاري إذا كان العقار محفظا.",
  "618-10": "لا يعتبر البائع متأخرا إذا كان التأخير ناتجا عن قوة قاهرة أو ظروف استثنائية خارجة عن إرادته تعترف بها السلطات الحكومية.",
  "10-618": "يمكن للمشتري بموافقة البائع إذا كان العقار محفظا أن يطلب من المحافظ على الأملاك العقارية إجراء تقييد احتياطي بناء على عقد البيع الابتدائي وذلك للحفاظ المؤقت على حقوقه.\nيبقى التقييد الاحتياطي ساري المفعول إلى غاية تقييد عقد البيع النهائي بالرسم العقاري الخاص بالمبيع.\nبمجرد إجراء التقييد الاحتياطي، يمنع على المحافظ على الأملاك العقارية تسليم نظير الرسم العقاري إلى البائع.\nيتم تعيين رتبة تقييد العقد النهائي بناء على تاريخ التقييد الاحتياطي.",
  "618-11": "يتحلل المشتري من العقد الابتدائي الابتدائي ويسترد كل أمواله المدفوعة مع التعويض إذا لم يلتزم البائع بتقديم الضمانة البنكية المنصوص عليها.",
  "11-618": "لا تخضع لأحكام الفصل 9-618 المشار إليه أعلاه، المؤسسات العمومية والشركات التي يعود مجموع رأسمالها للدولة أو لأي شخص معنوي آخر خاضع للقانون العام.",
  "618-12": "يبرم عقد البيع النهائي بعد انتهاء الأشغال وحصول العقار على رخصة السكن أو شهادة المطابقة وتسوية الرسم العقاري بشكل كامل.",
  "12-618": "في حالة التأخر عن أداء الدفعات حسب المراحل المنصوص عليها في الفصل 6-618 أعلاه، يتحمل المشتري تعويضا لا يتعدى 1% عن كل شهر من المبلغ الواجب دفعه، على أن لا يتجاوز هذا التعويض 10% في السنة.\nفي حالة تأخر البائع عن إنجاز العقار في الأجل المحدد فإنه يتحمل تعويضا بنسبة 1% عن كل شهر من المبلغ المؤدى على أن لا يتجاوز هذا التعويض 10% في السنة.\nغير أن هذا التعويض عن التأخير لا يطبق إلا بعد مرور شهر من تاريخ توصل الطرف المخل بالتزاماته بإشعار يوجهه إليه الطرف الآخر بإحدى الطرق المنصوص عليها في الفصل 37 وما يليه من الظهير الشريف بمثابة قانون رقم 447-74-1 الصادر بتاريخ 11 من رمضان 1394 (28 سبتمبر 1974) بالمصادقة على نص قانون المسطرة المدنية.",
  "618-13": "يتعين على المشتري دفع ما تبقى من ثمن العقار (30%) عند تحرير عقد البيع النهائي وتسلم المفاتيح.",
  "13-618": "لا يمكن للمشتري التخلي عن حقوقه المترتبة عن بيع العقار في طور الإنجاز لشخص آخر إلا بعد توجيه إعلام بذلك إلى البائع برسالة مضمونة مع الإشعار بالتوصل وبشرط أن يتم التخلي وفق الكيفية وضمن الشروط التي تم بها إبرام العقد الابتدائي.\nتنتقل بقوة القانون حقوق والتزامات البائع إلى المشتري الجديد.",
  "618-14": "إذا رفض أحد الطرفين إبرام عقد البيع النهائي بعد انتهاء الأشغال، جاز للطرف الآخر اللجوء إلى القضاء لطلب إجبار الخصم أو الحصول على حكم يقوم مقام عقد البيع النهائي.",
  "14-618": "في حالة فسخ العقد من أحد الأطراف يستحق المتضرر من الفسخ تعويضا لا يزيد على 10% من ثمن البيع.",
  "618-15": "عقد البيع النهائي لعقار في طور الإنجاز يسري على الرسوم العقارية بمجرد تدوينه بالمحافظة العقارية المختصة.",
  "15-618": "لا يعتبر العقار محل البيع منجزا، ولو تم الانتهاء من بنائه، إلا بعد الحصول على رخصة السكنى أو شهادة المطابقة وعند الاقتضاء بتقديم البائع للمشتري شهادة تثبت أن العقار مطابق لدفتر التحملات إذا طالب المشتري بذلك.",
  "618-16": "تطبق أحكام هذا الباب على جميع البنايات السكنية والتجارية والمهنية المعدة للملكية المشتركة أو المفرزة.",
  "16-618": "يبرم العقد النهائي طبقا لمقتضيات الفصل 3-618 المشار إليه أعلاه وذلك بعد أداء المبلغ الإجمالي للعقار أو للجزء المفرز من العقار، محل عقد البيع الابتدائي.",
  "618-17": "تعتبر باطلة بطلانا مطلقا كل الشروط والاتفاقات التي تخالف أحكام هذا الباب أو تحرم المشتري من حقوقه وحماية الضمانات الممنوحة له.",
  "17-618": "تحدد بنص تنظيمي تعريفة إبرام المحررات المتعلقة بعقدي البيع الابتدائي والنهائي[159].",
  "618-18": "تختص المحاكم الابتدائية الواقع العقار في دائرتها بالنظر في جميع المنازعات الناشئة عن تطبيق عقود بيع العقارات في طور الإنجاز.",
  "18-618": "يتعين على البائع بمجرد حصوله على رخصة السكنى أو شهادة المطابقة، وعلى أبعد تقدير داخل ثلاثين يوما الموالية لتاريخهما أن يخبر المشتري بذلك بواسطة رسالة مضمونة مع إشعار بالتوصل وأن يطلب تجزيء الرسم العقاري موضوع الملكية التي أقيم عليها العقار من أجل إحداث رسم عقاري خاص لكل جزء مفرز إذا كان العقار محفظا.",
  "618-19": "يجوز للمشتري التنازل عن حقوقه الواردة في العقد الابتدائي للغير بعد موافقة البائع الصريحة وبمقتضى محرر قانوني مماثل للعقد الابتدائي.",
  "19-618": "إذا رفض أحد الطرفين إتمام البيع داخل أجل ثلاثين يوما من تاريخ توصله بالإشعار المنصوص عليه في الفصل 18-618 أعلاه فيمكن للطرف المتضرر اللجوء إلى المحكمة لطلب إتمام البيع أو فسخ العقد الابتدائي.\nيعتبر الحكم النهائي الصادر بإتمام البيع بمثابة عقد البيع النهائي.",
  "618-20": "يلتزم البائع بإشعار المشتري بتقدم مراحل البناء بشكل دوري وكلما طلب المشتري ذلك.",
  "20-618": "لا تنتقل ملكية الأجزاء المبيعة إلى المشتري إلا من تاريخ إبرام العقد النهائي أو صدور الحكم النهائي في الدعوى إن كان العقار غير محفظ أو في طور التحفيظ وتنتقل الملكية بعد تقييد العقد النهائي أو الحكم بالسجل العقاري إذا كان العقار محفظا."
};
